// Erzeugt von tools/make_changelog.py aus CHANGELOG.md – nicht von Hand ändern.
'use strict';
const CHANGELOG = [{"build": "20261125-0943","title": "Küster Ruprecht und seine ausgebüxten Klingelbeutel","rows": [["h","Neu – Küster Ruprecht"],["b","Auf dem Vorplatz der Sonnenkathedrale steht jetzt Küster Ruprecht, eine neue Figur aus Blender: Glatze, runde Brille, schwarzer Talar mit Beffchen und ein langer Kollektenstab, an dessen Haken nichts mehr hängt."],["b","Seit dem Fluch sind ihm die Klingelbeutel ausgeflogen, und sie sammeln jetzt auf eigene Rechnung. Er bittet dich, drei von ihnen auf der Flucht zu erwischen."],["b","Jeder erwischte Beutel zählt mit (\"KOLLEKTE 1/3\" …). Nach dem dritten bedankt er sich mit seinem alten Sammelteller (Gold +2, Glück +1) und 2000 Gold \"als Rückerstattung\"."],["b","Mit Wortwechsel über Zinsen in der Kirche, wie immer in allen 8 Sprachen."],["h","Beim Testen ansehen"],["b","Ist der Auftrag klar, und lassen sich drei fliehende Beutel gut erwischen?"]]},{"build": "20261125-0930","title": "Der Klingelbeutel und drei neue Urkunden","rows": [["h","Neu – Klingelbeutel"],["b","In der Sonnenkathedrale und im Sonnenturm schweben jetzt Klingelbeutel herum: besessene Kollektenbeutel aus rotem Samt an langen Holzstäben, mit Goldring, Quaste, Glöckchen und gierig glühenden Augen. Sie sind Blender-Modelle wie die anderen neuen Gegner."],["b","Ein Klingelbeutel schwebt heran, bimmelt (\"EINE KLEINE SPENDE?\") und stößt zu. Statt dich zu verletzen, klaut er Gold (4 %, höchstens 300) und flieht prall gefüllt nach oben (\"DANKE FÜR DIE SPENDE!\")."],["b","Erwischst du ihn auf der Flucht, bekommst du die Spende mit 50 % Zinsen zurück (\"SPENDENQUITTUNG!\"). Entkommt er, ist das Gold weg."],["b","Hast du kein Gold, gibt es nur einen Stups."],["b","Im Bestiarium: Er sammelt seit 1452 für die Dachsanierung, und das Dach ist immer noch undicht."],["h","Neu – drei Urkunden"],["b","Quietschvergnügt: 50 Treffer mit dem Gummihuhn."],["b","Kettenreaktion: Ein einziger Blitz der Leidener Flasche trifft fünf Gegner."],["b","Spendenquittung: Einen Klingelbeutel auf der Flucht erwischen."],["h","Beim Testen ansehen"],["b","Ist der Klingelbeutel lustig oder eher lästig? Ist er auf der Flucht gut zu erwischen?"]]},{"build": "20261125-0914","title": "Zwei neue Nebenwaffen: Gummihuhn und Leidener Flasche","rows": [["h","Neu – Gummihuhn"],["b","Eine neue Nebenwaffe: Das Gummihuhn hüpft quietschend über den Boden, prallt von Wänden ab und trifft jeden Gegner auf seinem Weg, auch mehrere hintereinander. Bei jedem Aufprall und Treffer quietscht es."],["b","Heiliger Sturm (Nebenwaffe gedrückt halten, ab 10 Herzen): Ein Regen aus elf Gummihühnern fällt vom Himmel."],["b","Zu finden in Kerzen im Hotel Krat und in der Kantine."],["h","Neu – Leidener Flasche"],["b","Eine Glasflasche voller Elektrizität aus dem Galvani-Labor: Sie fliegt fast gerade und zerplatzt am ersten Gegner. Der Blitz springt dann auf bis zu vier weitere Gegner in der Nähe über. Zerplatzt sie an einer Wand, springen die Funken auf Gegner in der Nähe."],["b","Heiliger Sturm: ein Gewitter, das dreimal in alle Gegner im Bild einschlägt."],["b","Zu finden in Kerzen im Galvani-Laboratorium, im Automatenwerk und auf der Himmelsbrücke."],["b","Beim ersten Aufheben erklärt ein Hinweis, was die neue Waffe kann (in allen 8 Sprachen)."],["h","Beim Testen ansehen"],["b","Fühlen sich die beiden neuen Waffen nützlich an? Ist der Kettenblitz zu stark oder zu schwach?"],["b","Nervt das Quietschen, oder macht es Spaß?"]]},{"build": "20261121-0256","title": "Gustav knurrt","rows": [["h","Behoben"],["b","Grottenolm Gustav knurrt jetzt hörbar, wenn er dich gehört hat und das \"!\" über seinem Kopf erscheint. Bisher blieb er dabei stumm."],["h","Beim Testen ansehen"],["b","Hört man das Knurren rechtzeitig, bevor er zustößt?"]]},{"build": "20261121-0219","title": "Grottenolm Gustav im Unterirdischen Kanal","rows": [["h","Neu – Grottenolm Gustav: er sieht nichts, aber er hört alles"],["b","Im Unterirdischen Kanal, hinter dem zweiten Becken, liegt jetzt ein neuer Zwischengegner: Grottenolm Gustav, ein riesiger, blinder Höhlenmolch mit rosiger Haut und roten, gefiederten Kiemen. Er ist ein Blender-Modell wie die anderen neuen Gegner."],["b","Er ist blind und jagt nach Gehör. Lärm machen: Gehen in seiner Nähe, Rennen, Landen nach einem Sprung, Peitschenhiebe und Wurfwaffen. Hat er etwas gehört, zeigt ein Schallring am Helden das an. Über seinem Kopf erscheint ein \"!\", dann schnellt er flach auf die Stelle zu."],["b","Wer still steht oder weit weg leise geht, bleibt ungehört. Hört er lange nichts, kriecht er suchend umher (\"?\")."],["b","Von hinten sitzen Treffer besser. Getroffen braucht er einen Moment, bis er sich umdreht."],["b","Seinen flachen Vorstößen kannst du ausweichen, indem du über ihn springst. Prallt er an die Wand, ist er kurz benommen."],["b","Ist das Geräusch weit weg, spuckt er einen Schleimklumpen dorthin, und die Pfütze ätzt eine Weile."],["b","Ab halber Energie ruft er \"ICH HÖRE DEIN HERZ!\", hört noch feiner und schlägt mit dem Schwanz gegen die Wand. Dann fallen Tropfsteine von der Decke, angekündigt durch rieselnden Staub."],["b","Eigene Musik: ein leises Schleich-Stück in d-Moll mit gezupftem Bass, Rimclicks statt Trommeln und einer Melodie, die immer wieder innehält."],["b","Vor dem Kampf fragt er \"WER DA?\" und hört sogar deinen Magen (in allen 8 Sprachen)."],["b","Lohn: die Filzpantoffeln. Wer leise kommt, trifft besser: kritische Treffer +6 %."],["h","Beim Testen ansehen"],["b","Ist verständlich, was Gustav hört und was nicht?"],["b","Macht das Anschleichen Spaß, oder fühlt es sich zu langsam an?"]]},{"build": "20261121-0035","title": "Kleiderschrank-Tango, Gewitter-Toccata und fünf neue Urkunden","rows": [["h","Neu – eigene Musik für zwei Zwischengegner"],["b","Kleiderschrank-Tango für Kunibert in Zimmer 13: a-Moll, gemächliche 112 BPM, mit Habanera-Rhythmus im Bass, Marcato-Akkorden und einer Melodie mit Vorschlägen und einer frechen kleinen None. Der Schrank tanzt."],["b","Gewitter-Toccata für Kirchturmhahn Kasimir auf der Himmelsbrücke: e-Moll, 126 BPM. Gebrochene Akkorde wehen wie Windböen, die Pauke grollt alle vier Takte wie ferner Donner, und die Melodie steigt in großen Bögen."],["b","Der Arrangeur macht aus beiden Stücken jeweils fünf Durchgänge mit Orchesterstimmen (Streicher, Blech, Flöte, Harfe, Glockenspiel, Pauken), ohne dass sich etwas wiederholt."],["h","Neu – fünf Urkunden vom Amt für Heldentaten"],["b","Petri Heil: Angler Anselm besiegen. Diesmal hing der Haken auf der anderen Seite."],["b","Zugabe!: Primadonna Ottilie fünfmal während ihres Knickses treffen. Sie hält es für Applaus."],["b","Erwischt!: Madame Vitrina zehnmal beim Gleiten erwischen. Sie streitet alles ab."],["b","Kleiderordnung: Kunibert besiegen, ohne verschluckt zu werden."],["b","Blitzableiter: Kasimir ohne Blitztreffer besiegen. Die Vorhersage lag wieder daneben."],["b","Wie immer zahlt das Amt je Urkunde eine Aufwandsentschädigung. Texte in allen 8 Sprachen."],["h","Beim Testen ansehen"],["b","Passen Tango und Toccata zu den Kämpfen? Sind sie nicht zu hektisch?"],["b","Sind Kleiderordnung und Blitzableiter machbar, aber eine Herausforderung?"]]},{"build": "20261120-1004","title": "Kirchturmhahn Kasimir auf der Himmelsbrücke","rows": [["h","Neu – Kirchturmhahn Kasimir, der Vater aller Wetterhähne"],["b","Auf der Himmelsbrücke, zwischen zwei Lücken im Steg, wartet jetzt ein neuer Zwischengegner: Kirchturmhahn Kasimir, der Ur-Wetterhahn vom Kathedralenturm. Er ist ein Blender-Modell aus Kupfer mit Grünspan und hängt noch an seinem abgerissenen Turmstab mit Windkreuz und vergoldetem Turmknauf."],["b","Damit hat jetzt auch die Kathedrale mit der Himmelsbrücke einen Zwischengegner."],["b","Stoß: Wie seine kleinen Verwandten dreht er sich wie eine Wetterfahne zu dir, eine Ziellinie blinkt, dann stößt er zu. Rammt er dabei den Steg, steckt er fest. Dann ist er wehrlos, und Treffer sitzen besser."],["b","Windstoß: Er fliegt an den Rand, dreht sich auf seinem Stab und bläst über den Steg. Der Wind schiebt dich weg, und Dachschiefer fliegt mit. Über flachen Schiefer springst du, unter hohem bleibst du unten."],["b","Blitze: Er kräht in den Himmel, und an markierten Stellen auf dem Steg schlagen Blitze ein. Die Male blinken immer schneller, also rechtzeitig weggehen."],["b","Ab halber Energie ruft er \"STURMWARNUNG!\": Es regnet, zwei kleine Wetterhähne kommen ihm zu Hilfe, und die Blitze fallen dreifach und zweimal hintereinander."],["b","Ein neues Geräusch für sein Krähen: ein echtes \"Kikeriki\"."],["b","Vor dem Kampf kräht er um Mitternacht und behauptet, er irre sich nie, er drehe sich nur (in allen 8 Sprachen)."],["b","Lohn: die Windrose vom Turmknauf (Glück +2, und manchmal trägt dich der Wind aus der Bahn eines Treffers)."],["h","Beim Testen ansehen"],["b","Sind die Blitzmale gut zu sehen, auch im Regen?"],["b","Ist der Windstoß fair, oder schiebt er zu stark?"]]},{"build": "20261120-0919","title": "Kleiderschrank Kunibert in Zimmer 13","rows": [["h","Neu – Kleiderschrank Kunibert, seit 1391 verschlossen"],["b","In Zimmer 13 des Hotels Krat (die Tür mit dem Schlüsselbund) wartet jetzt ein neuer Zwischengegner: Kleiderschrank Kunibert, ein besessener Nussbaumschrank mit Kranzgesims, Klauenfüßen und Messingknäufen. Er ist ein Blender-Modell, wie die anderen neuen Gegner."],["b","Er kippelt von Kante zu Kante auf dich zu, und seine Augen glühen durch die Schlüssellöcher."],["b","Bügel: Er öffnet einen Spalt und wirft Kleiderbügel wie Bumerangs. Sie fliegen auch wieder zurück."],["b","Stampfen: Er hüpft und schlägt auf. Über die Staubwellen, die dann über den Boden rollen, musst du springen."],["b","Schlucken: Er reißt die Türen auf und saugt dich an. Wer hineingerät, wird verschluckt und mit einem \"PFUI! STAUBIG!\" wieder ausgespuckt. Weit offen ist aber auch sein Innerstes ungeschützt, und Treffer sitzen dann besser."],["b","Ab halber Energie flattern Motten heraus, und er stampft zweimal hintereinander."],["b","Vor dem Kampf besteht er darauf, kein bloßer Schrank zu sein, sondern ein Nussbaum-Kleiderschrank mit Kranzgesims (in allen 8 Sprachen)."],["b","Der Gast-Geist und der Tentakel verkriechen sich während des Kampfs."],["b","Lohn: der Smoking von 1391 (Rüstung, Abwehr +5, Glück +1). Er riecht nur leicht nach Mottenkugeln."],["h","Beim Testen ansehen"],["b","Merkt man rechtzeitig, dass er gleich schluckt? Kann man dem Sog gut entkommen?"],["b","Kommen die Bügel-Bumerangs auf dem Rückweg überraschend?"]]},{"build": "20261120-0839","title": "Madame Vitrina in der Lichterpassage, eine Arie für Ottilie","rows": [["h","Neu – Madame Vitrina, Königin der Schaufensterpuppen"],["b","In der Ladenzeile der Lichterpassage wartet jetzt eine neue Zwischengegnerin: Madame Vitrina, die Blender-Schaufensterpuppe in Königsgröße mit Krone, Hermelinumhang und violettem Kleid."],["b","Wie ihre Puppen bewegt sie sich nur, wenn du wegschaust. Schaust du sie an, erstarrt sie mit einem Porzellanklirren in einer neuen Pose."],["b","Drehst du dir den Rücken zu, gleitet sie auf ihrem Ständer heran und schlägt mit dem Fächer zu. Bist du weit weg, wirft sie Hutschachteln."],["b","Erwischt: Drehst du dich zu ihr um, während sie gerade gleitet, gerät sie aus der Fassung. Dann sitzen Treffer besser."],["b","Wer sie zu lange anstarrt, hört \"STARR NICHT SO!\", und schon steht sie ihm im Rücken."],["b","Sie ruft Schaufensterpuppen an beide Ränder der Ladenzeile, damit du nicht alles im Blick behältst. Ab halber Energie ruft sie \"SCHAUFENSTERWECHSEL!\" und wird schneller."],["b","Vor dem Kampf behauptet sie, sie stehe seit 1889 völlig reglos da (in allen 8 Sprachen)."],["b","Lohn: die Puppenkrone (Abwehr +2, Glück +1). Sie steht dir erstaunlich gut."],["h","Neu – Ottilies eigene Arie"],["b","Primadonna Ottilie singt jetzt ihre eigene Arie statt der Orgel-Toccata: d-Moll im Dreivierteltakt, eine Sopranlinie in großen Bögen bis zum gefürchteten hohen Cis, Walzerbegleitung, Pauken und Becken. Der Arrangeur macht daraus gut drei Minuten mit Orchesterstimmen, ohne dass sich etwas wiederholt."],["h","Beim Testen ansehen"],["b","Madame Vitrina: Ist das Spiel mit der Blickrichtung verständlich? Kommt das \"Erwischt!\" oft genug?"],["b","Passt die Arie zum Kampf, und ist sie nicht zu hektisch?"]]},{"build": "20261120-0758","title": "Neue Zwischengegnerin: Primadonna Ottilie im Hoftheater","rows": [["h","Neu – Primadonna Ottilie auf der Bühne"],["b","Im Zuschauerraum des Hoftheaters hebt sich jetzt nicht nur der Vorhang: Auf der Bühne wartet Primadonna Ottilie, eine Geister-Operndiva in weinrotem Samt mit Goldborte, Perücke und Diadem, modelliert in Blender. Sie hat 1847 ihre letzte Arie gesungen, und das Publikum ist nie gegangen."],["b","Arie: Mit ausgebreiteten Armen singt sie Notenketten, die in Wellen über die Bühne fliegen. Ducken oder drüberspringen."],["b","Verbeugung: Nach jeder Arie macht sie einen tiefen Knicks und fragt \"APPLAUS?\". Jetzt sitzen Treffer besser."],["b","Scheinwerfer: Sie weist in den Saal, ein Lichtkegel erscheint schwach am Bühnenrand und streicht dann glühend über den Boden. Wer im Lichtfleck steht, verbrennt."],["b","Zweiter Akt: Sie verlangt \"ZUGABE!\", singt schneller und zweistimmig, und das Geisterpublikum ruft \"BRAVO! BRAVA!\" und wirft Rosen auf die Bühne."],["b","Vor dem Kampf erklärt sie, dass sie noch nicht eingesungen ist und dass der Bösewicht am Ende stirbt (in allen 8 Sprachen)."],["b","Lohn: ihr Opernglas (Glück +2, kritische Treffer +4). Es sieht jede Schwachstelle, auch vom dritten Rang."],["h","Beim Testen ansehen"],["b","Sind die Notenketten gut zu lesen? Weißt du, wann du ducken und wann springen musst?"],["b","Kommt der Scheinwerfer fair angekündigt?"]]},{"build": "20261120-0752","title": "Neuer Zwischenboss unter Wasser: Angler Anselm","rows": [["h","Neu – Angler Anselm in der versunkenen Kapelle"],["b","Der erste Bosskampf unter Wasser: Mit dem Taucherhelm geht es in der versunkenen Kapelle hinab zum Altar. Dort lauert Angler Anselm, ein Tiefsee-Anglerfisch, modelliert in Blender. Als Köder trägt er das Ewige Licht der Kapelle an seiner Angel, im dunklen Becken das hellste Licht weit und breit."],["b","Flackert das Licht grell, nimmt er Maß und schießt mit aufgerissenem Maul auf dich zu. Danach ist er erschöpft, kippt zur Seite und schielt mit X-Augen. Dann sitzen Treffer besser."],["b","Mit vollen Backen pustet er einen Fächer aus Luftblasen, die langsam aufsteigen."],["b","Ab halber Energie flackert das Licht wie bei einem Stromausfall, und er schnappt zweimal hintereinander zu."],["b","Er war der Küster der Kapelle, seit sie abgesoffen ist. Vor dem Kampf erklärt er, warum die Lampe an seiner Stirn hängt (in allen 8 Sprachen)."],["b","Lohn: das Ewige Licht, ein Amulett mit MP +6 und Glück +1. Es brennt auch unter Wasser. Frag nicht, wie."],["b","Der Wegweiser schickt dich erst zu ihm, wenn du den Taucherhelm hast."],["h","Beim Testen ansehen"],["b","Ist der Kampf unter Wasser fair? Kannst du dem Ausfall rechtzeitig ausweichen, obwohl man im Wasser langsamer ist?"],["b","Ist das Licht im dunklen Becken gut zu sehen, auch auf dem Fernseher?"]]},{"build": "20261120-0619","title": "Hafenfeuer, Waffenaltäre und präzisere Sprünge","rows": [["h","Schiffsreise"],["b","Zwischen Burg und Takelage steht ein Hafenfeuer auf einer Felsschäre. Seine Laterne dreht sich und zieht eine Lichtspur über die Wellen. Das Modell wurde in Blender gebaut und in Unreal Engine 5.8.4 geprüft."],["h","Heldenwahl"],["b","In drei beleuchteten Nischen stehen Morgenstern, Breitschwert und Hellebarde neben den zugehörigen Helden. Die Galerie dreht sich in beide Richtungen durch. Auf dem Touchscreen lässt sich eine Karte antippen und mit einem zweiten Tipp bestätigen."],["h","Bewegung"],["b","Ein kurz vor der Landung oder am Ende eines Hiebs angetippter Sprung wird acht Spielschritte lang vorgemerkt. Beim Aufsetzen auf Stein, Schnee und nassem Boden hängen Partikel, Ton und Controller-Feedback von Untergrund und Fallgeschwindigkeit ab."],["h","Beim Testen ansehen"],["b","In der Heldenwahl von Henrik nach links zu Kaspar wechseln. Auf dem Achterdeck den Doppelsprung verbrauchen und den Sprung kurz vor dem Aufsetzen noch einmal antippen."]]},{"build": "20261120-0430","title": "Xbox-Absturz behoben, Wegweiser an, Englisch zuerst, schnellere Aufzüge, Kleinvieh in HD-3D","rows": [["h","Geändert – nach euren Rückmeldungen"],["b","Wegweiser standardmäßig an: Der goldene Pfeil zum nächsten Ziel ist jetzt für alle eingeschaltet, auch in alten Spielständen, in denen er aus war. Wer ihn nicht möchte, schaltet ihn unter OPTIONEN wieder ab."],["b","Sprache: Neue Spieler starten auf Englisch. In den Optionen wechselt die Sprache in der Reihenfolge Englisch, Deutsch, Spanisch, Chinesisch, Japanisch, Italienisch, Rumänisch und zuletzt Französisch. Wer schon eine Sprache gewählt hat, behält sie."],["b","Schnellere Aufzüge: Die großen Aufzüge (Hotel, Eis, Pumpwerk, Himmel) fahren gut anderthalbmal so schnell und ziehen kräftiger an, halten aber weiter sanft. Auch die Pendelplattformen hinter den Bossen, der Rätselaufzug und der Eilgang im Paternoster sind flotter."],["b","Paternoster ohne Trennwand: Der Pfeiler zwischen Aufwärts- und Abwärtsschacht ist weg. Man kann jetzt quer über die Schächte springen, aus der Kabine in die Gegenkabine umsteigen oder sich ein Stockwerk tiefer fallen lassen."],["h","Behoben"],["b","Edge schloss sich auf der Xbox beim Betreten des Kolosseums: Seit dem letzten Build lagen auf der Xbox alle vorbereiteten Bilder im Arbeitsspeicher. Grafik und Arbeitsspeicher teilen sich dort einen knappen Topf, das war vermutlich zu viel (am PC ließ sich der Absturz nicht nachstellen). Die Bilder liegen jetzt wieder auf der Grafikkarte."],["b","Schwarzer Hintergrund nach einem Grafik-Neustart: Wirft der Browser die Bilder auf der Grafikkarte weg, merkt das Spiel das jetzt. Es sichert den Fortsetzungspunkt und lädt sich neu, statt mit schwarzem Hintergrund weiterzulaufen."],["b","Alte Version im Zwischenspeicher: Das Spiel prüft jetzt alle zehn Minuten und beim Zurückkehren in den Tab, ob es eine neue Version gibt. Im Titelmenü lädt es sie sofort, mitten im Spiel kommt erst ein Hinweis (in allen 8 Sprachen), und geladen wird beim nächsten Besuch im Titelmenü. Auf der Xbox, wo Tabs oft tagelang offen bleiben, sollte damit keine alte Grafik mehr auftauchen."],["b","Mit dem Taucherhelm im Kanal gefangen: Ein Schwimmzug brachte die Füße nur knapp unter die Uferkante, und am Ufer löste der Sprung einen Wandsprung aus, der vom Ufer wegschob. Jetzt gibt es im Wasser keine Wandsprünge mehr. Wer zum Ufer drückt und nah genug an der Kante ist, steigt automatisch aus dem Becken."],["h","Neu – sieben weitere Figuren in HD-3D"],["b","Brief (Hauptpoststelle): flattert mit Papierflügeln, die Klappe geht auf und zu, Kulleraugen."],["b","Nachnahme-Paket: schläft, wacht auf und klappt beim Sprung die Deckel weit auf wie einen Kiefer, mit einer Zahnreihe darunter."],["b","Schiebepaket: Paketschnur, Klebeband, Briefmarke in vier Farben, Zerbrechlich-Etikett."],["b","Qualle (versunkene Kapelle): durchscheinende Glocke mit leuchtendem Kern, schwingende Tentakel."],["b","Mondkalb: Mondgestein mit Kratern, das wie ein geflecktes Kalb aussieht, goldene Hörnchen, eine Käseglocke am Hals."],["b","Kerzen-Mimik: böse rote Augen, Zickzack-Grinsen, ein Maul voller Zähne und tippelnde Beinchen. Die Kerze leuchtet etwas schwächer, weil das Wachs sonst überstrahlt."],["b","Auch Grammophon, Errungenschaften und Gewissensfragen haben jetzt den gut lesbaren Auswahlbalken aus dem Optionsmenü."],["h","Beim Testen ansehen"],["b","Xbox: Kommst du ohne Absturz ins Kolosseum? Bleiben die Hintergründe sichtbar?"],["b","Findest du mit dem Wegweiser jetzt zuverlässig zum nächsten Ziel? Gibt es Stellen, an denen der Pfeil fehlt oder in die Irre führt?"],["b","Kanal mit Taucherhelm: Kommst du an jedem Ufer gut aus dem Wasser?"],["b","Paternoster: Ist das Queren jetzt angenehm, oder fällt man zu leicht in den Schacht?"],["b","Sind die Aufzüge jetzt schnell genug?"]]},{"build": "20261120-0233","title": "Xbox-Korrekturen, ruhigere Musik, Welpe Krümel","rows": [["h","Behoben – schwarzer Hintergrund auf der Xbox"],["b","Auf der Xbox wurde der Hintergrund zum Beispiel beim Golem schwarz, an anderen Stellen auch. Ursache: Wenn der Grafikspeicher knapp wird, startet der Browser seinen Grafikteil neu. Danach waren alle vorbereiteten Bilder leer, die das Spiel auf der Grafikkarte zwischengespeichert hatte: Kulissen, Hintergründe und Teile der Schrift."],["b","Auf dem PC ließ sich das genau so nachstellen, indem man den Grafikteil des Browsers absichtlich abstürzen lässt."],["b","Auf der Xbox liegen diese Zwischenbilder jetzt im Arbeitsspeicher, der bei einem Grafik-Neustart erhalten bleibt. Im Test blieb der Golemraum danach unverändert, und die Bildrate war gleich."],["b","Passiert so ein Neustart auf einem anderen Gerät, merkt sich das Spiel das und nutzt ab dem nächsten Start ebenfalls den Arbeitsspeicher."],["h","Behoben – Optionsmenü schwer lesbar"],["b","Die gewählte Zeile im Optionsmenü liegt jetzt auf einem dunklen Balken mit Goldkanten und einem Pfeil davor. Die Schrift wackelt nicht mehr und wird nicht mehr verdeckt."],["b","Denselben Balken haben jetzt auch Grammophon, Errungenschaften und Gewissensfragen. Vorher war die Auswahl dort nur ein schwacher Goldschimmer, der auf dem Fernseher kaum zu sehen war."],["h","Geändert – Musik ruhiger"],["b","Die Erkundungslieder laufen etwa 10 % langsamer, zum Beispiel der Burghof mit 158 statt 176 Schlägen pro Minute. Bosslieder sind 5 % langsamer. Langsame Stücke und Fanfaren bleiben, wie sie waren."],["b","Die leisen Hi-Hat-Schläge zwischen den Zählzeiten sind deutlich leiser, und beim Erkunden spielt das Schlagzeug zurückhaltender. Sobald Gegner kommen, wird es wie bisher lauter."],["h","Neu – Welpe Krümel"],["b","Nach dem Sieg über Kettenhund Brutus liegt im Zwinger neben dem Stachelhalsband auch sein Jüngster: Krümel, ein Welpe mit Schlappohren und rotem Halsband mit Glöckchen, modelliert in Blender."],["b","Krümel ist der erste Begleiter, der am Boden läuft statt zu schweben. Er rennt hinter dem Helden her und springt nach, wenn der Held höher steht."],["b","Gegner in der Nähe schnappt er sich und beißt zu. Wie die anderen Begleiter steigt er dabei bis Stufe 9 auf."],["b","Ab und zu meldet er sich zu Wort, etwa \"(KAUT AUF DEINER PEITSCHE.)\", in allen 8 Sprachen."],["b","Anlegen im Pausenmenü unter AUSRÜSTUNG, Platz Begleiter."],["h","Neu – Aktenordner in HD-3D"],["b","Die lebenden Aktenordner im Amt sind neu aus Blender: geschlossen, halb und ganz aufgeklappt, in allen Ordnerfarben."],["h","Beim Testen ansehen"],["b","Auf der Xbox: Bleibt der Hintergrund beim Golem und in anderen Räumen jetzt sichtbar, auch nach längerem Spielen? Läuft das Spiel genauso flüssig wie vorher?"],["b","Ist die Musik jetzt angenehm, oder ist sie an manchen Stellen zu langsam geworden?"],["b","Mit Krümel durch einen Raum mit Treppen und Plattformen laufen: Kommt er gut hinterher, und beißt er oft genug?"]]},{"build": "20261120-0028","title": "Neuer Zwischenboss: Kettenhund Brutus im Zwinger","rows": [["h","Neu – Kettenhund Brutus"],["b","Im Zwinger, dem Gang zwischen Torstube und Hotelfassade, liegt jetzt der Wachhund des Grafen an der Kette: ein schwerer Mastiff mit Stachelhalsband, modelliert in Blender. Er wartet seit 1823 auf seinen Spaziergang."],["b","Die Kette hängt an einem Pfahl mitten in der Arena und reicht nur so weit. Springt Brutus nach einem Helden außer Reichweite, reißt ihn die Kette mitten im Sprung zurück. Dann liegt er auf dem Rücken, zappelt mit den Beinen und steckt mehr Schaden ein."],["b","Wer in Reichweite steht, wird angesprungen."],["b","Er bellt ein \"WAU!\", das als Schallwelle über den Boden rollt (drüberspringen). In jeder Sprache bellt er anders."],["b","Ab halber Energie lockert sich der Pfahl: Die Kette reicht weiter, Brutus wird schneller und bellt zweimal."],["b","Mit Auftritt, Beinamen (\"Hunde, die bellen, beißen doch\"), Wortgeplänkel, Bestiariums-Eintrag und einem Eintrag im Wegweiser."],["b","Beute: das Stachelhalsband (Amulett, +2 Angriff)."],["h","Beim Testen ansehen"],["b","Im Zwinger am Rand der Arena bleiben und ihn ins Leere springen lassen: Ist gut zu erkennen, wie weit die Kette reicht?"],["b","Ist der Kampf früh im Spiel fair, oder ist Brutus zu stark?"]]},{"build": "20261119-2129","title": "HD-3D: Holzpuppe und Schaufensterpuppe neu aus Blender","rows": [["h","Neu – HD-3D-Gegner"],["b","Die Holzpuppe am Bahnhof, im Labor und im Theater ist jetzt ein Gepäckträger aus Holz in Blender: rote Mütze mit Messingschild, rote Jacke mit Messingknöpfen, Knopfaugen und Kugelgelenke. Dazu kommen eigene Posen fürs Ausholen und den Satz nach vorn."],["b","Die Schaufensterpuppen in der Passage sind jetzt Porzellanpuppen aus Blender: auf ihrem Ständer, mit Glockenrock, Hut und Feder, in allen 4 Kleidern und 6 Posen."],["b","Ihr Verhalten ist unverändert. Die Schaufensterpuppen bewegen sich nur, solange man ihnen den Rücken zukehrt."],["h","Beim Testen ansehen"],["b","In der Passage einmal wegschauen und wieder hinsehen: Ist die neue Pose gut zu erkennen?"]]},{"build": "20261119-2126","title": "HD-3D: Skelett, Eisskelett und Ritter neu aus Blender","rows": [["h","Neu – HD-3D-Gegner"],["b","Die beiden häufigsten Gegner im Schloss, Skelett und Ritter, sind jetzt in Blender modelliert und gerendert, wie die neuen Gegner der letzten Updates. Bisher kamen sie aus einem einfachen 2D-Gerüst."],["b","Das Skelett hat glühende Augenhöhlen, einen zerschlissenen Lendenschurz und ein eigenes Bild für den Knochenwurf."],["b","Das Eisskelett hat bereifte Knochen, Eiszapfen an den Rippen und kalt leuchtende Augen."],["b","Der Ritter trägt Plattenrüstung mit Topfhelm, rotem Busch und Wappenrock. Für Ausholen und Ausfall hat er jetzt eigene Posen: Er zieht das Schwert zurück und stößt dann mit gestrecktem Arm zu."],["b","Ihr Verhalten ist unverändert."],["h","Beim Testen ansehen"],["b","In der Gruft und im Kerker: Sind Skelett und Ritter gut vom Hintergrund zu unterscheiden?"],["b","Ist der Ausfall des Ritters jetzt besser zu lesen?"]]},{"build": "20261119-2016","title": "Drei neue Urkunden","rows": [["h","Neu – Urkunden"],["b","\"Sterneküche\": alle 8 Gerichte der Kantinenküche essen. Nachschlag zählt nicht."],["b","\"Wetterfühlig\": Wetterhähne insgesamt fünfmal in eine Wand oder den Boden rammen lassen."],["b","\"Darf ich abklatschen?\": das Walzerpaar besiegen."],["b","Wie alle Urkunden zahlt das Amt dafür je 500 Gold Aufwandsentschädigung. Die Urkunden stehen im Status auf der Urkundenseite."],["h","Beim Testen ansehen"],["b","Einem Wetterhahn ausweichen, bis er fünfmal feststeckt: Kommt die Urkunde?"]]},{"build": "20261119-2012","title": "Zwei neue Gegner: Hüpfsarg und Walzerpaar","rows": [["h","Neu – Hüpfsarg"],["b","In Kerker, Kapelle und Gruftgang sowie im Hotel (Zimmer 13 hat einen Dauergast) stehen jetzt Särge aus dunklem Holz, die wie Dekoration aussehen."],["b","Kommt der Held näher, hüpft ihm der Sarg in drei Sprüngen hinterher. Jeder Aufprall staubt und rumst."],["b","Dann geht der Deckel einen Spalt auf und zwei Augen glühen. Gleich danach springt er ganz auf: Drin sitzt der mürrische Vormieter mit Schlafmütze, schimpft und scheucht zwei Fledermäuse hinaus."],["b","Mit geschlossenem Deckel prallt fast jeder Schlag ab. Nur offen nimmt der Sarg vollen Schaden."],["b","Er lässt manchmal Knochen für die Kieselsuppe der Kantinenküche fallen."],["b","Modell und Posen sind in Blender gebaut und gerendert, dazu gibt es einen Bestiariums-Eintrag."],["h","Neu – Walzerpaar"],["b","Im Foyer, im Ballsaal, im Theaterfoyer und im Theater tanzt jetzt ein Geisterpaar, er im Frack, sie im Ballkleid. Seit 1802 tanzen die beiden denselben Walzer."],["b","Sie drehen sich im Dreivierteltakt über den Boden und kommen dem Helden zwei Takte lang näher, auf der Eins mit einem großen Schritt."],["b","Dann verbeugen sie sich, und ein Fächer aus fünf Noten fliegt im Bogen heraus. Man kann zwischen den Noten hindurch oder darüber springen."],["b","Manchmal tritt er ihr dabei auf den Fuß, und sie beschwert sich, in jeder Sprache."],["b","Das Paar lässt manchmal Ektoplasma für den Geisterpudding der Kantinenküche fallen."],["b","Modell und Drehung sind in Blender gebaut und gerendert, dazu gibt es einen Bestiariums-Eintrag."],["h","Beim Testen ansehen"],["b","Im Kerker warten, bis der Sarg aufgeht, und dann zuschlagen."],["b","Ist das offene Zeitfenster lang genug, und stören die Fledermäuse zu sehr?"],["b","Im Ballsaal den Notenfächer überspringen."],["b","Sind die Noten vor dem Hintergrund gut zu sehen?"]]},{"build": "20261119-1932","title": "Neuer Gegner: der Wetterhahn","rows": [["h","Neu – Wetterhahn"],["b","Im Burghof, im Zwinger, auf dem Wehrgang, im Turm, auf den Brücken, auf dem Schiff und im Wald gleitet jetzt ein Wetterhahn aus Kupfer mit Grünspan durch die Luft. Er hat sich vom Kirchturm losgerissen und sitzt noch auf seinem eisernen Windpfeil."],["b","Ohne Held in der Nähe dreht er sich ab und zu im Wind."],["b","Zum Angriff kräht er, in jeder Sprache anders. Dann dreht er sich wie eine Wetterfahne zum Helden, die Pfeilspitze glüht und eine Ziellinie blinkt. Kurz vor dem Stoß steht die Richtung fest."],["b","Dann stößt er geradeaus. Wer ausweicht, lässt ihn in die Wand oder den Boden rammen: Dort steckt er eine Weile fest, zappelt und tut niemandem weh."],["b","Er lässt manchmal Rost für das Uhrwerk-Gulasch der Kantinenküche fallen."],["b","Modell und Posen sind in Blender gebaut und gerendert, dazu gibt es einen Bestiariums-Eintrag."],["h","Beim Testen ansehen"],["b","Im Burghof dem Stoß ausweichen und den feststeckenden Hahn verhauen."],["b","Ist die Ziellinie gut zu lesen, und ist die Zeit bis zum Stoß fair?"]]},{"build": "20261119-1638","title": "Neuer Gegner: der Galvanifrosch","rows": [["h","Neu – Galvanifrosch"],["b","Am Bahnhof, im Automatenwerk, im Fundbüro, auf der Versuchsstrecke, in der Rohrpost und in der Weltausstellung sitzen jetzt mechanische Frösche mit Kupferspule und Glaskuppel auf dem Rücken."],["b","Kommt der Held näher, duckt sich der Frosch und Funken springen über seinen Rücken. Dann springt er auf den Helden zu."],["b","Beim Aufkommen entlädt sich die Spule, und ein Blitzbogen läuft über den Boden. Wer in dem Moment in der Luft ist, bleibt heil."],["b","Er lässt manchmal ein Zahnrad für das Uhrwerk-Gulasch der Kantinenküche fallen."],["b","Modell und Posen sind in Blender gebaut und gerendert, dazu gibt es einen Bestiariums-Eintrag."],["b","Die Bestiariums-Texte von Gargoyle, Frostgeist und Galvanifrosch sind jetzt in allen Sprachen höchstens zwei Zeilen lang."],["h","Beim Testen ansehen"],["b","Am Bahnhof auf einen Frosch zugehen, auf die Funken achten und über die Entladung springen."],["b","Ist die Vorwarnung lang genug?"]]},{"build": "20261119-1616","title": "Die Kantinenküche: Zutaten sammeln, Gerichte kochen","rows": [["h","Neu – Kantinenküche"],["b","20 Gegnerarten lassen mit etwas Glück ihre eigene Zutat fallen, zum Beispiel Fledermausflügel, Ektoplasma, Rostflocken, Kieselsteine, Raureif oder Mondmilch."],["b","Jeder Sieg ohne Zutat macht die nächste etwas wahrscheinlicher, damit niemand ewig farmen muss."],["b","Im Laden der Kantinenchefin gibt es eine dritte Seite, KOCHEN, mit acht Gerichten: Kieselsuppe, Spinnwebwatte, Flügel süßsauer, Raureif-Sorbet, Geisterpudding, Fischstäbchen, Mondmilchreis und Uhrwerk-Gulasch."],["b","Jedes Gericht stärkt beim ersten Mal dauerhaft (Max-HP, Max-MP, Angriff, Abwehr oder Glück). Jeder Nachschlag heilt voll."],["b","Die Köchin kommentiert jedes Gericht in allen 8 Sprachen."],["b","Das Bestiarium zeigt bei jedem Gegner seine Beute, sobald man sie einmal gefunden hat."],["b","Die Gerichte sind in Blender modelliert und gerendert."],["h","Beim Testen ansehen"],["b","Ein paar Fledermäuse, Geister oder Ritter besiegen und auf die kleinen Zutaten achten, die herausfallen."],["b","In der Kantine im Laden mit ←→ zu KOCHEN blättern und ein Gericht kochen. Steigen die Werte?"],["b","Im Bestiarium nachsehen, ob die Beute dort steht."]]},{"build": "20261119-1552","title": "Neuer Gegner: der Frostgeist","rows": [["h","Neu – Frostgeist"],["b","In der Eishöhle, im Eiskeller, im Spiegeltunnel, im Spiegelschacht, im Kaleidoskop und im Glasturm schwebt jetzt ein Kapuzengeist mit Eiskrone."],["b","Er hält Abstand schräg über dem Helden und hebt die Hände: An der Decke glitzern drei Risse, kurz darauf fallen dort Eiszapfen."],["b","Wer auf die Risse achtet, hat genug Zeit zum Ausweichen. Getroffen zerspringt der Geist in Eissplitter."],["b","Modell und Posen sind in Blender gebaut und gerendert, dazu gibt es einen Bestiariums-Eintrag."],["h","Beim Testen ansehen"],["b","Im Eiskeller oder im Spiegeltunnel unter einem Frostgeist stehen bleiben und auf die glitzernden Risse an der Decke achten."],["b","Ist die Vorwarnung lang genug, um den Zapfen auszuweichen?"]]},{"build": "20261119-1532","title": "Neuer Gegner: die Höhlenspinne","rows": [["h","Neu – Höhlenspinne"],["b","In Höhlen, Grüften, Eishöhlen, im Wald, im Spiegelsaal und in Bibliotheken hängen jetzt Spinnen an einem Faden unter der Decke."],["b","Geht der Held darunter vorbei, seilt sich die Spinne ab, pendelt und spuckt Netze."],["b","Ein Netz klebt: knapp zwei Sekunden halbes Tempo und schwächere Sprünge."],["b","Nach einer Weile klettert sie wieder hinauf. Treffbar ist sie jederzeit, am besten solange sie am Faden hängt."],["b","Modell und Posen sind in Blender gebaut und gerendert, dazu gibt es einen Bestiariums-Eintrag."],["h","Beim Testen ansehen"],["b","In der Registratur, am Mondmeer, in der Tropfsteinklamm oder im Spiegelschacht unter einer Spinne durchgehen."],["b","Ein Netz einfangen und auf das langsamere Tempo achten."]]},{"build": "20261119-1403","title": "Neuer Zwischenboss: der Wachhauptmann","rows": [["h","Neu – Wachhauptmann im Verlies"],["b","Hinter der rissigen Wand am Glasturm wartet jetzt der Wachhauptmann: die Schildwache in Schwarz und Gold, anderthalbmal so groß, mit Umhang. Modell und Posen sind in Blender gebaut."],["b","Der Turmschild fängt jeden Treffer von vorn ab. Verwundbar ist der Hauptmann von hinten, von oben auf den Helm und nach jedem Angriff."],["b","Seine Angriffe: Lanzenstoß, Schildansturm quer durch die Arena und Sprung mit Schockwellen nach beiden Seiten. Ab halber Energie sticht er zweimal zu und schickt doppelte Wellen."],["b","Beiname, Wortgeplänkel und Bestiariums-Eintrag in acht Sprachen. Der Hauptmann ist auch im Bossrausch dabei."],["b","Lohn: der Turmschild (Rüstung, Verteidigung 8)."],["h","Beim Testen ansehen"],["b","Im Verlies den Hauptmann rufen und alle drei Angriffe abwarten."],["b","Über die Schockwellen springen und nach dem Ansturm von hinten zuschlagen."]]},{"build": "20261119-1343","title": "Neuer Gegner: die Schildwache","rows": [["h","Neu – Schildwache"],["b","In Hallen, Galerien, Thronsaal, Ballsaal, Kathedrale, Hotel, Theater und Bibliothek patrouillieren jetzt gepanzerte Wachen mit Turmschild und Lanze."],["b","Der Schild fängt jeden Treffer von vorn ab, es sprühen nur Funken."],["b","Die Wache zieht die Lanze zurück, die Spitze blitzt auf, dann stößt sie weit vor."],["b","Verwundbar ist sie von hinten, von oben auf den Helm und kurz nach dem Stoß, wenn der Schild herabhängt."],["b","Modell und Posen sind in Blender gebaut und gerendert, dazu gibt es einen Bestiariums-Eintrag."],["h","Beim Testen ansehen"],["b","Über eine Schildwache springen und sie von hinten treffen."],["b","Den Lanzenstoß abwarten und danach zuschlagen."]]},{"build": "20261119-1322","title": "Tagesprüfung im Kolosseum","rows": [["h","Neu – Tagesprüfung"],["b","Der Ansager bietet jetzt jeden Tag eine eigene Prüfung an: fünf Wellen und zwei Regeln, am selben Tag für alle gleich."],["b","Die Regeln: Champions überall, Fledermausplage, Goldrausch (dreifacher Lohn), Mondschwerkraft, Hektik (Gegner doppelt so flink) und Glaskanone (Gegner haben halbes Leben, du nimmst doppelten Schaden)."],["b","Der erste Sieg des Tages zahlt vollen Lohn und ein Elixier, jede Wiederholung ein Viertel. Die Bestzeit des Tages steht im Menü."],["b","Freigeschaltet nach der Bronze-Prüfung ab Stufe 5."],["h","Beim Testen ansehen"],["b","Im Kolosseum den Ansager ansprechen, die Tagesprüfung wählen und auf die Regeln achten."],["b","Nach dem Sieg oder einem Tod müssen Schwerkraft und Schaden wieder normal sein."]]},{"build": "20261119-1114","title": "Neuer Gegner: der Wasserspeier","rows": [["h","Neu – Wasserspeier"],["b","In Türmen, Hallen, Galerien, Bibliotheken, Grüften, im Hof und auf der Brücke hocken jetzt Wasserspeier als Steinfiguren auf Simsen über Abgründen."],["b","Als Stein sind sie unverwundbar, Treffer schlagen nur Funken."],["b","Geht der Held darunter vorbei, glühen ihre Augen auf. Dann reißen sie sich los und stürzen sich auf ihn."],["b","Auf dem mühsamen Rückflug zu ihrem Sims sind sie verwundbar."],["b","Das Modell ist in Blender gebaut und gerendert (Stein, Erwachen, Flügelschlag, Sturzflug), dazu gibt es einen Bestiariums-Eintrag."],["h","Beim Testen ansehen"],["b","Unter einem Wasserspeier hindurchgehen, dem Sturz ausweichen und ihn im Rückflug treffen."],["b","Ein Raum soll bei jedem Besuch dieselben Wasserspeier an denselben Plätzen haben."]]},{"build": "20261119-0634","title": "Drei neue Waffen mit eigenen Künsten","rows": [["h","Neu – Waffen"],["b","Frostklinge (Eiskeller): Ihr Eisschlag lässt Gegner knapp zwei Sekunden zu Eis erstarren."],["b","Sternenstab (Planetarium): Fünf Sternschnuppen schlagen vor dir ein."],["b","Donnerpeitsche: Lohn für den ersten Bossrausch mit allen Bossen. Ihr Kettenblitz springt vom ersten Getroffenen zu bis zu drei weiteren Gegnern."],["b","Wie alle Waffenkünste lösen auch diese bei drei Treffern in Folge aus."],["h","Neu – Bestiarium"],["b","Die Kerzenmimik hat jetzt ihren eigenen Eintrag."],["h","Beim Testen ansehen"],["b","Frostklinge und Sternenstab suchen und gegen Gruppen ausprobieren."],["b","Eingefrorene Gegner dürfen sich nicht bewegen und tauen sichtbar wieder auf."]]},{"build": "20261119-0606","title": "Zwei neue Nebenaufträge","rows": [["h","Neu – Das Gulasch des Grafen"],["b","Die Kantinenchefin braucht für das Leibgericht des Grafen Drachenpfeffer, Mondkäse und ein Riesenei."],["b","Die Zutaten liegen im Eiskeller, am Mondmeer und in der Requisite des Theaters."],["b","Lohn: die Goldene Schöpfkelle (mehr Leben, heilt langsam)."],["h","Neu – Die verlorene Zeit"],["b","Dem Uhrmacher in der Zeigerkammer sind drei Zahnräder davongerollt. Seitdem geht das große Uhrwerk nach dem Mond."],["b","Die Zahnräder liegen im Automatenwerk, in der Pendelhalle und im Glockenstuhl."],["b","Lohn: die Unruh (mehr Magie und Glück)."],["h","Besser"],["b","Das Auftragsbuch zeigt jetzt bis zu fünf Aufträge auf einer Seite."],["h","Beim Testen ansehen"],["b","Kantinenchefin und Uhrmacher ansprechen, die Stücke suchen und abgeben."],["b","Im Auftragsbuch prüfen, ob alles lesbar bleibt."]]},{"build": "20261119-0532","title": "Waffenkünste und Kerzenmimik","rows": [["h","Neu – Waffenkünste"],["b","Drei Treffer kurz hintereinander entfesseln die Kunst deiner Waffe. Drei Punkte über dem Kopf zeigen, wie weit die Kette ist."],["b","Ohne Waffe gibt es einen Wuchtschlag mit doppeltem Schaden."],["b","Silberschwert: Ein Silberkreuz fliegt weit und schneidet durch alles."],["b","Blutrune: Blutzoll heilt dich für jeden getroffenen Gegner."],["b","Drachenzahn: Eine Feuerwalze aus fünf Flammensäulen läuft über den Boden."],["b","Reißzahn: Getroffene Gegner bluten viermal nach."],["h","Neu – Kerzenmimik"],["b","Manchmal ist eine Kerze keine Kerze. Wer sie trifft, weckt eine bissige Mimik, die auf dich zuhüpft."],["b","Aufmerksame sehen es vorher: Mimiken blinzeln ab und zu mit roten Augen."],["b","Besiegt lässt sie einen großen Geldsack und die Beute der Kerze fallen."],["h","Beim Testen ansehen"],["b","Mit jeder Waffe dreimal hintereinander treffen und die Künste vergleichen, auch gegen Bosse."],["b","In Kerker und Gruftgang auf blinzelnde Kerzen achten."]]},{"build": "20261119-0510","title": "Bossrausch und neue 3D-Kulissen","rows": [["h","Neu – Bossrausch"],["b","Im Kolosseum steht ein Gong. Ab fünf besiegten Bossen ruft er sie alle noch einmal, einen nach dem anderen und auf Zeit."],["b","Gekämpft wird in den echten Kammern der Bosse, zwischen zwei Kämpfen gibt es 30 % Leben zurück."],["b","Wer fällt, wacht an der Speicherkammer auf. Dein Spielstand bleibt dabei unberührt."],["b","Gold, Bestzeit und Rekord werden festgehalten. Wer alle Bosse schafft, bekommt die Urkunde \"Nachtragend\"."],["b","Der Graf bleibt außen vor: Sein Ende gehört der Geschichte."],["h","Neu – 3D-Kulissen"],["b","Gladiatorenstatuen im Kolosseum, Sarkophage in Kerker, Gruftgang und Verlies."],["b","Globen in Registratur, Dachboden und Schatzkammer, Konzertflügel im Hotel und im Theaterfoyer."],["b","Orgeln im Zuschauerraum und in der Sonnenkathedrale, Eiskristalle im Eiskeller. In einem davon steckt jemand fest."],["h","Beim Testen ansehen"],["b","Kolosseum: Gong mit ↑ anschlagen, einen ganzen Lauf spielen und die Übergänge zwischen den Kammern prüfen."],["b","Mitten im Rausch sterben: Danach müssen Kammern und Spielstand wie vorher sein."],["b","Die neuen Kulissen in den genannten Räumen ansehen und auf Überdeckungen achten."]]},{"build": "20261119-0437","title": "Geheimnisjagd, große Boss-Auftritte und Klangkulissen","rows": [["h","Neu – Die Jagd nach den goldenen Gummihühnern"],["b","Dem Hühnerwart in der Eingangshalle sind zwölf goldene Gummihühner entlaufen. Sie sitzen an abgelegenen Stellen im ganzen Schloss."],["b","Die Hühner quieken: Je näher du kommst, desto öfter und lauter, und zwar aus der richtigen Richtung."],["b","Der Hühnerwart (↑) zeigt deine Funde und kennt zu jedem Huhn ein Rätsel."],["b","Finderlohn bei 3, 6, 9 und 12 Hühnern: Gold, ein Elixier, dauerhaft mehr Angriff und zuletzt ein treuer Begleiter samt Urkunde \"Baron der Hühner\"."],["h","Neu – Große Boss-Auftritte"],["b","Der Raum wird dunkel, ein Lichtkegel fällt auf den Boss, und sein Name schlägt mit Orchesterschlag ins Bild."],["b","Jeder Boss trägt jetzt einen eigenen Beinamen, in allen acht Sprachen."],["h","Neu – Klangkulissen je Region"],["b","Alle Regionen haben jetzt ein eigenes Klangbett, neu dazu die Sonnenkathedrale, die Turmspitze, das Theater und das Labor."],["b","Dazu kommen seltene Einzelgeräusche: Gewitter und Krähen im Hof, Bahnhofsgong und ferne Züge, das stimmende Orchester im Theater, Glocken im Turm, Möwen am Schiff und vieles mehr."],["h","Beim Testen ansehen"],["b","Eingangshalle: Hühnerwart ansprechen, Rätsel durchblättern, dann im Kolosseum dem Quieken folgen."],["b","Einen Boss rufen: Lichtkegel, Einschlag und Beiname prüfen, auch im Zusammenspiel mit dem Wortgeplänkel."],["b","Mit Kopfhörern durch mehrere Regionen gehen und auf Lautstärke und Stimmung der Klangkulissen achten."]]},{"build": "20261119-0414","title": "Gladiatorenprüfung, Champions mit Eigenschaften und Folgen des Gewissens","rows": [["h","Neu – Gladiatorenprüfung im Kolosseum"],["b","Der Ansager im Kolosseum schickt dich mit ↑ in die Prüfung: drei Stufen (Bronze, Silber, Gold) mit je fünf Wellen."],["b","Silber verlangt Stufe 8 und den Bronze-Sieg, Gold verlangt Stufe 15 und den Silber-Sieg."],["b","Der erste Sieg zahlt Gold und einen Trank oder ein Elixier. Gold schenkt zusätzlich dauerhaft mehr Angriff, Wiederholungen zahlen ein Viertel."],["b","Deine Bestzeit bleibt stehen, die Gold-Prüfung bringt die Urkunde \"Brot und Spiele\"."],["h","Neu – Champions mit Eigenschaften"],["b","Goldene Gegner sind jetzt flammend (Feuerspur), eilig (schneller), gepanzert (drei Schilde) oder spaltend (zerfallen in zwei Hälften)."],["b","Die Eigenschaft steht über dem Gegner, sobald du nah genug bist."],["h","Neu – Dein Gewissen hat Folgen"],["b","Reine Weste: Ein Schutzengel rettet dich etwa alle drei Spielminuten vor dem Tod."],["b","Schwarze Seele: Die Steuerfahndung schickt dir ab und zu einen eiligen Champion-Ritter hinterher."],["h","Besser"],["b","Beim ersten Betreten einer Region erscheint ihr Name groß im Bild, das alte BEREIT?/LOS! entfällt im Schloss."],["h","Beim Testen ansehen"],["b","Kolosseum: Ansager ansprechen, Bronze spielen, danach das Menü auf die Sperren von Silber und Gold prüfen."],["b","Während einer Prüfung sterben: Sperre und Kamera müssen sich sauber lösen."],["b","Champions aller vier Arten suchen und die Schilde des gepanzerten zählen."]]},{"build": "20261119-0341","title": "Gewissen, drei Enden, Opferschreine und drastische Pixel-Tode","rows": [["h","Neu – Gewissensfragen"],["b","Im Schloss warten sechs Entscheidungen: anständig oder einträglich. Jede Antwort gilt für immer."],["b","Zu finden im Kerker, Gruftgang, Zimmer 13, in der Sakristei, im Amt für Heldentaten und auf dem Mondmeer. Ein goldenes Fragezeichen zeigt die Stelle, ↑ startet die Frage."],["b","Mindestens zwei Antworten mehr auf der anständigen Seite ergeben \"Reine Weste\": Du erleidest weniger Schaden."],["b","Mindestens zwei mehr auf der schäbigen Seite ergeben \"Schwarze Seele\": Du richtest mehr Schaden an."],["b","Die Chronik erzählt am Ende eine von drei Fassungen. Dazu gibt es zwei neue Urkunden."],["h","Neu – Opferschreine"],["b","In allen sechs Speicherkammern steht ein Schrein. Dort tauschst du Gold gegen dauerhafte Ränge in Angriff, Leben und Magie, je Wert bis Rang 5."],["h","Neu – Blut und Brocken"],["b","Gegner zerplatzen je nach Material in Blut, Knochen, Blech, Öl, Papier, Schleim, Pflanzenfasern, Käse oder Eis."],["b","Brocken springen über den Boden, Blut und Öl hinterlassen Flecken bis zum Raumwechsel."],["b","Wem das zu viel ist: Optionen → BLUT UND BROCKEN schaltet es ab."],["h","Beim Testen ansehen"],["b","Kerker oder Gruftgang: Gewissensfrage öffnen, mit ↑↓ wählen, bestätigen. Sind Text und Folgen klar?"],["b","Statusseite: Steht rechts das Gewissen mit den sechs Feldern?"],["b","Speicherkammer: Schrein mit ↑ öffnen und einen Rang kaufen. Sind die Preise fair?"],["b","Mehrere Gegner besiegen: Sind die Brocken schön oder zu viel? Auf der Xbox bitte besonders auf Ruckler achten."],["b","Optionen: BLUT UND BROCKEN aus- und wieder einschalten."]]},{"build": "20261119-0259","title": "Klügere Gegner: Ritter-Ausfall, Skelett-Rücksprung, Schritte je Untergrund","rows": [["h","Neu – Gegner"],["b","Ritter holen aus und stoßen dann mit einem Ausfall vor. Ein roter Streifen am Boden zeigt vorher, wie weit der Stoß reicht."],["b","Wer den Ritter beim Ausholen trifft, wehrt den Ausfall ab. Nach dem Stoß muss er kurz verschnaufen, das ist deine Gelegenheit."],["b","Skelette springen zurück, wenn du ihnen zu nah kommst, und werfen dann aus sicherer Entfernung weiter."],["h","Neu – Ton"],["b","Schritte klingen je nach Untergrund: Dielen in Bibliothek, Hotel und Theater, Metall in Werk, Bahnhof und Labor, knirschender Schnee im Eis, weiches Moos in Höhlen, Wald und Wintergarten."],["h","Beim Testen ansehen"],["b","Ritter: Ist der Ausfall gut zu lesen und fair? Lässt er sich durch einen Treffer beim Ausholen abwehren?"],["b","Skelette: Fühlt sich der Rücksprung gut an? Bitte auf Skelette an Kanten achten, besonders in Höhle und Eishöhle."],["b","Schritte in Bibliothek, Werk, Eiskeller und Kanal: Klingen sie passend und nicht zu laut?"]]},{"build": "20261119-0241","title": "Bibliothek wieder frei, Trefferwucht, goldene Champions, mehr Tiefe im Bild","rows": [["h","Behoben"],["b","Stage 4-2 (Bibliothek): Der linke Wandsprung-Schacht war oben zugebaut, der Weg zur oberen Galerie und zum Ausgang rechts oben damit gesperrt. Jetzt führt ein Loch neben der Tür hindurch, unten im Schacht erklärt ein Hinweis den Wandsprung."],["h","Neu – Trefferwucht"],["b","Gewöhnliche Gegner werden bei einem Treffer zurückgestoßen und sind kurz aus dem Tritt. Danach sind sie einen Moment standfest, damit niemand endlos weggeprügelt wird."],["b","Die Peitsche zieht beim Ausschlagen einen hellen Bogen durch die Luft."],["h","Neu – Goldene Champions"],["b","In manchen Räumen wartet ein goldener Gegner mit Krone und eigener Lebensleiste. Er hält dreimal so viel aus und trifft härter."],["b","Dafür zahlt er vierfache Erfahrung, einen großen Geldbeutel und ein großes Herz."],["b","Für zehn besiegte Champions gibt es die Urkunde \"Goldgräber\"."],["h","Neu – Tiefe im Bild"],["b","Unter Decken und Stegen, neben Wänden und über dem Boden liegen in Innenräumen jetzt weiche Schatten."],["h","Beim Testen ansehen"],["b","Stage 4-2: Vom Steg links im Wandsprung-Schacht nach oben, über die Lücke und zum Ausgang rechts oben."],["b","Skelette und Panther treffen: Fühlt sich der Rückstoß gut an, oder macht er Kämpfe zu leicht?"],["b","Einen Champion suchen und besiegen: Sind Krone, Leiste und Belohnung klar zu erkennen?"],["b","Gruft, Bibliothek und Kolosseum: Wirken die neuen Schatten stimmig?"]]},{"build": "20261119-0216","title": "Lebendiges Schloss: Kleintiere, Höhlenflora, neue Menüs, schneller zurück ins Spiel","rows": [["h","Neu – Das Schloss lebt"],["b","Ratten und Mäuse flitzen davon, Krähen und Tauben fliegen auf, Motten umkreisen die Kerzen, Spinnen ziehen sich am Faden hoch, Frösche hüpfen weg, im Wintergarten flattern Schmetterlinge."],["b","Im Eis wohnen jetzt Pinguine. Kommt man ihnen zu nah, rutschen sie auf dem Bauch davon."],["b","Höhlen bekommen Leuchtpilze, Glühwürmchen und Wurzelvorhänge."],["b","Alle Tiere sind harmlos und verschwinden im Bosskampf."],["h","Neu – Menüs"],["b","Status, Ausrüstung, Karte und alle Pausenseiten haben einen gestalteten Grund mit Mauerwerk, Mond, Schloss-Silhouette und goldenen Eckbeschlägen."],["b","Auf der Statusseite steht dein Held in einer goldenen Nische (bei schmalen Bildschirmen ausgeblendet)."],["h","Besser"],["b","Nach dem Tod geht es deutlich schneller weiter: 2,1 statt 3,6 Sekunden. Mit Sprung oder Angriff kürzt du auf 1,5 Sekunden ab."],["h","Beim Testen ansehen"],["b","Eiskeller: Rutschen die Pinguine weg, wenn du näher kommst?"],["b","Gruftgang, Zwinger und Kanal: Stören die Tiere irgendwo beim Spielen oder sehen sie falsch aus?"],["b","Kanal und Klamm: Sind Leuchtpilze und Wurzeln schön, oder lenken sie von Gegnern ab?"],["b","Pausenmenü und Statusseite: Ist alles gut lesbar?"],["b","Einmal sterben: Fühlt sich der Neustart jetzt flott an?"]]},{"build": "20261119-0132","title": "Bossansagen liegen über allen Bossen","rows": [["h","Besser"],["b","Ring und Landepunkt werden jetzt nach dem Licht gezeichnet. Riesige Bosse wie der Steingolem verdecken ihre Ansage nicht mehr."],["h","Beim Testen ansehen"],["b","Steingolem: Erscheint der rote Ring vor jedem Laser sichtbar über dem Boss?"]]},{"build": "20261119-0121","title": "Bossansagen: der Ring umschließt jetzt auch riesige Bosse","rows": [["h","Besser"],["b","Der Ansage-Ring richtet sich nach der Größe des Bosses und ist kräftiger gezeichnet. Bei Steingolem und Amtsschimmel war er vorher kaum zu sehen."],["h","Beim Testen ansehen"],["b","Steingolem: Ist der Ring vor dem Laser und dem Faustschlag gut zu erkennen?"]]},{"build": "20261119-0038","title": "Gesamtpolitur: lesbare Bosse, eigene Kammern, neue Kulissen, besseres Licht","rows": [["h","Neu – Bossangriffe lesen"],["b","Alle 18 Bosse kündigen ihre großen Angriffe an: Sie halten kurz inne, blitzen auf, ein Ring zieht sich um sie zusammen, dazu ein heller Warnton."],["b","Sturzflüge zeigen ihre Bahn bis zum Ziel. Bei springenden Bossen (Knochenriese, Sonnenwächter, Frankiermaschine, Schreibtischtäter) zeigt ein roter Streifen am Boden den genauen Landepunkt."],["b","Geschosse haben jetzt einen dunklen Hof und einen roten Kern. Sie bleiben so vor jedem Hintergrund sichtbar."],["h","Neu – Räume mit eigenem Gesicht"],["b","Die Speicher- und Warpkammern sehen je Region anders aus: Tropfsteine und Kristalle in den Katakomben, Bücherwände im Bergfried, Zahnräder im Turm, Banner in der Kathedrale, Glaswände und Efeu im Wintergarten, Samtvorhänge am Thron, Schädelregale in der Kasematte, Wappen in der Torstube."],["b","Neue Kulissen aus Blender: Schleusen mit Wasserfällen und Rohrleitungen im Kanal, Grubenausbau, Laternen und Loren im Stollen, ein Riesenteleskop in der Sternkuppel, Käsebohrtürme auf dem Mond und Palmen im Wintergarten."],["h","Besser"],["b","Licht: Theaterfoyer, Sonnenkathedrale, Sakristei und Orangerie überstrahlen nicht mehr. Die Blitze im Ballsaal sind sanfter und blenden weniger."],["b","Weniger Warten: Bekannte Regionen blenden beim Wechsel nur noch kurz auf, das BEREIT?/LOS! kommt nur beim ersten Besuch."],["h","Beim Testen ansehen"],["b","Bosskampf gegen Riesenfledermaus oder Steingolem: Ist jede Ansage rechtzeitig zu sehen, und fühlt sich das kurze Innehalten gut an oder bremst es?"],["b","Sprünge von Knochenriese, Sonnenwächter, Frankiermaschine und Schreibtischtäter: Hilft der rote Streifen beim Ausweichen?"],["b","Kanal, Golemstollen und Sternkuppel: Bleiben Held, Gegner und Plattformen vor den neuen Kulissen gut erkennbar?"],["b","Alle Speicherkammern einmal betreten, besonders Orangerie und Vorzimmer."],["b","Ballsaal und Theaterfoyer: Ist das Licht jetzt angenehm?"],["b","Regionswechsel hin und zurück: Geht es flott weiter? Auf der Xbox bitte besonders auf Ruckler achten."]]},{"build": "20261118-2149","title": "Abkürzungstüren: acht Riegeltüren verbinden das Schloss","rows": [["h","Neu – Abkürzungen"],["b","Acht schwere Eichentüren verbinden Räume, die auf der Karte nebeneinanderliegen, zu Fuß aber weit auseinander waren. Die größten sparen über tausend Kacheln Laufweg."],["b","Von der Riegelseite öffnest du sie mit ↑ oder einem Peitschenhieb. Danach bleiben sie für immer in beide Richtungen offen."],["b","Von der anderen Seite sind sie verriegelt, mit Warnschild und wechselnden Sprüchen. So weißt du früh, dass dort später ein Weg entsteht."],["b","Keine Tür überspringt einen Boss, ein Siegel oder ein Relikt: Der Riegel sitzt immer auf der Seite, die man später erreicht."],["h","Die acht Wege"],["b","Kolosseum zur Eingangshalle, gleich hinter dem ersten Relikt"],["b","Brunnenschacht zur Großen Halle"],["b","Palmenhaus zur Eishöhle"],["b","Verlies zum Palmenhaus"],["b","Automatenwerk zum Fundbüro"],["b","Ende der Versuchsstrecke zum Amt für Heldentaten: Die Rückfahrt entfällt"],["b","Thronregion zum Spiegeltunnel"],["b","Zuschauerraum zur Menschenfalle"],["h","Neu – Karte und Wegweiser"],["b","Die Karte zeigt jede Tür nach Zustand: hell mit Riegel, rot von der Gegenseite, grün wenn offen. Offene Abkürzungen erscheinen als Gang."],["b","Der Wegweiser nutzt offene Abkürzungen und führt auch zu Riegeln, die du selbst öffnen kannst. An eine verschlossene Gegenseite schickt er dich nie."],["b","Neue Urkunde für alle acht Türen."],["h","Beim Testen ansehen"],["b","Fallen die Türen im Vorbeigehen auf, und ist klar, dass man sie öffnen kann?"],["b","Fühlt sich das Aufschwingen wuchtig an, oder dauert es zu lange?"],["b","Welche Wege sind dir noch immer zu lang?"]]},{"build": "20261118-1356","title": "Bosskämpfe: Taumel, letztes Aufgebot, Finisher und Kampfakte","rows": [["h","Neu – Kampf (gilt für alle 18 Bosse)"],["b","Taumel: unter der Bossleiste liegt jetzt eine gelbe Leiste. Treffer füllen sie, Perfekt-Ausweichen und Konter füllen sie schneller. Ist sie voll, steht der Boss zwei Sekunden benommen da, mit Sternen über dem Kopf und einem passenden Spruch. Seine Helfer und alle Geschosse halten mit an, deine Treffer kommen schneller und härter durch, gepanzerte Bosse sind in dieser Zeit offen. Jeder weitere Taumel braucht mehr Treffer. Wer ablässt, verliert den Druck langsam wieder."],["b","Letztes Aufgebot: unter einem Viertel der Energie wird der Boss wütend, glüht und wird etwas schneller. Die Bossleiste färbt sich rot, eine kleine Marke zeigt vorher, wo das beginnt."],["b","Finisher: der letzte Treffer friert das Bild kurz als Scherenschnitt mit Strahlen und Schnitt ein."],["h","Neu – Kampfakte"],["b","Nach jedem Bosssieg erscheint ein kleiner Bericht: Zeit, kassierte Treffer, Taumel, Rang von S bis C und ein trockener Kommentar."],["b","Der Rang bringt Bonusgold. Dein bester Rang steht im Bestiarium neben dem Boss."],["h","Behoben"],["b","Die große Zeitlupe beim Tod eines Bosses lief bei fast allen Bossen nie, obwohl sie eingebaut war. Jetzt läuft sie."],["h","Beim Testen ansehen"],["b","Kommt der Taumel zu früh oder zu spät? Sind zwei Sekunden genug, um ihn auszunutzen?"],["b","Ist das letzte Aufgebot spürbar, aber noch fair?"],["b","Finisher-Bild: wirkt es wuchtig, oder ist der Hell-Dunkel-Wechsel unangenehm?"],["b","Passt die Kampfakte in deiner Sprache in den Kasten, und stört sie nicht beim Weitergehen?"]]},{"build": "20261118-0908","title": "Laufschritt gegen lange Wege, Randlicht auf allen Figuren","rows": [["h","Neu – Gameplay"],["b","Laufschritt: wer gut eine halbe Sekunde ohne Unterbrechung am Boden läuft, wird um 60 % schneller (Staub, Nachbilder, die Kamera schaut weiter voraus). Angriff, Ducken, Treffer, Richtungswechsel und Wände beenden ihn."],["b","Gilt nur am Boden: in der Luft zählt das normale Tempo, Sprungweiten bleiben praktisch gleich. Im Bosskampf und auf Eis gibt es keinen Laufschritt."],["h","Neu – Grafik"],["b","Randlicht: Kerzen, Fackeln, Feuerschalen, Feuerbälle und Zauber zeichnen jetzt eine helle Kante in ihrer Farbe auf Held, Gegner und Bosse – auf der Seite, die dem Licht zugewandt ist. Die Figuren stehen dadurch sichtbar im Raum (im Spar-Modus aus)."],["h","Beim Testen ansehen"],["b","Lange Gänge entlanglaufen: fühlt sich der Laufschritt gut an, kommt er zu früh oder zu spät? Stört er auf kurzen Plattformen?"],["b","Sprünge aus vollem Lauf: landest du noch dort, wo du willst?"],["b","Dunkle Räume mit Kerzen (Gruft, Kerker): wandert das Licht an Held und Gegnern mit, ist es zu stark oder zu schwach?"]]},{"build": "20261118-0852","title": "Changelog mit Sprungliste, Musik mit Raumklang, Dynamik und Überleitungen","rows": [["h","Neu – Changelog"],["b","Direkt zu den Änderungen springen: das Changelog öffnet jetzt mit einer Übersicht aller Versionen (Datum, Titel, farbige Marken für Grafik, Musik, Gameplay und Behoben). ↑↓ wählt, ←→ blättert, Sprung öffnet die Version, Angriff springt sofort zu \"Beim Testen ansehen\"."],["b","In einer Version zeigen Reiter die Abschnitte: Angriff springt zum nächsten, ←→ wechselt die Version, Sprung führt zurück zur Liste."],["b","NEU-Marke: Versionen seit deinem letzten Besuch sind grün markiert und werden im Menü gezählt."],["b","Das Changelog ist jetzt auch im Pausenmenü, du musst dafür nicht mehr zurück zum Titel."],["b","In CHANGELOG.md auf GitHub steht oben ein Inhaltsverzeichnis mit Links zu jeder Version."],["h","Neu – Musik"],["b","Raumklang: Streicher, Blech, Flöte, Harfe, Glockenspiel, Pauken und Flächen stehen jetzt tiefer im Hall als Melodie und Bass, wie ein Orchester in einer Schlosshalle (im Spar-Modus bleibt nur der Grundhall)."],["b","Dynamik: die Durchgänge sind nicht mehr gleich laut. Der ruhige Flötenteil ist deutlich leiser, das Tutti lauter."],["b","Überleitungen: vor jedem Tonartwechsel steht ein eigener Übergangstakt (Dominantakkord, Blech steigt auf, Harfenlauf, Paukenwirbel, Fill), statt dass die Tonart unvermittelt springt."],["b","Saubere Stimmführung: lange Töne von Streichern, Flöte und Glockenspiel reiben nicht mehr einen Halbton neben dem Akkord (in allen Stücken zusammen 268 solche Stellen). Die Streicher haben außerdem ein Vibrato."],["h","Beim Testen ansehen"],["b","Changelog aus der Pause öffnen: Liste, Sprung, Angriff zu \"Testen\", Reiter, Rückweg. Ist alles lesbar und die Steuerung klar?"],["b","Musik ein paar Minuten laufen lassen (Burghof oder Katakomben): sind die Übergänge schön, ist der Hall zu stark oder zu schwach, ist ein Teil zu leise? Ich kann die Musik prüfen und messen, aber nicht hören."],["b","Läuft es auf der Xbox weiter flüssig, wenn die Musik mit Hall spielt?"]]},{"build": "20261115-0409","title": "Fünf weitere Figuren aus Blender","rows": [["h","Neu – Figuren aus Blender"],["b","Der Bibliothekar (Bibliothek): Gelehrtenkappe, weißer Bart, runde Brille, violette Robe mit Goldsaum und -naht; er hält ein aufgeschlagenes Buch und blättert ab und zu um – auch in seinem Laden."],["b","Der Gefangene (Kerker): Skelett im zerrissenen Lumpen (die Rippen schauen durch), Fußfessel mit Kette zur Wand, Teetasse samt Untertasse; der Kiefer klappert beim Reden."],["b","Der Geist eines Speedrunners (Kaleidoskop): durchscheinend und flackernd, rotes Stirnband mit wehenden Enden, ein Schweif statt Beinen – nur die Stoppuhr ist nicht durchsichtig."],["b","Oberamtsrat Stempelmann (Amt für Heldentaten): grüner Augenschirm, runde Brille, schütteres Haar, Weste mit roter Krawatte, Ärmelschoner; am Stehpult saust der Stempel aufs Kissen."],["b","Fundsache Nr. 13 (Fundbüro): das Huhn auf der Fundkiste, mit Fundzettel am Bein; es pickt ab und zu."],["b","Damit sind bis auf den Portier (mit der wachsenden Nase) und den Tentakel alle Figuren aus Blender."],["h","Beim Testen ansehen"],["b","Bibliothek, Kerker, Kaleidoskop, Amt, Fundbüro: passen die Figuren, sind die Porträts im Gespräch gut zu erkennen?"]]},{"build": "20261115-0320","title": "Vier weitere Figuren aus Blender","rows": [["h","Neu – Figuren aus Blender"],["b","Knochen-Kalle (Gruftgang), Betriebsrat der Skelette: Schiebermütze, rote Armbinde und ein Schild mit \"STREIK\"."],["b","Friseur Anatol (Lichterpassage): Ringelhemd, weiße Schürze, Pomade, gezwirbelter Schnurrbart, zugekniffene Augen – die Schere klappert, an den Fingern Pflaster."],["b","Der Kartograf (Pendelhalle, oben): wildes weißes Haar, goldener Kneifer, langer Mantel, Kartenrollen unterm Arm, der Federkiel kritzelt, die Karte schleift am Boden."],["b","Kantinenchefin Schöpfkelle (Kantine): Kochhaube, rote Wangen, blaue Schürze, die Kelle rührt im Suppentopf – auch im Kantinen-Laden."],["b","Alle vier atmen (zwei Bilder) und zeigen sich auch im Gesprächsporträt; die Porträt-Ausschnitte sind angepasst."],["h","Beim Testen ansehen"],["b","Gruftgang, Lichterpassage, Pendelhalle oben, Kantine: passen die neuen Figuren in ihre Räume?"]]},{"build": "20261115-0214","title": "Glöckner, Bergführer und Uhrmacher aus Blender","rows": [["h","Neu – Figuren aus Blender"],["b","Der Glöckner (Glockenstuhl): gebückt in der Kutte mit Strick, Glatze mit Haarkranz, Watte in den Ohren, den Finger an den Lippen (\"Psst!\") und das Glockenseil in der Hand."],["b","Der Bergführer (Tropfsteinklamm): ein Skelett im Bergsteigerzeug – grüner Hut mit roter Borte und Feder, Kniebundhose, Hosenträger, Seil über der Schulter, Pickel."],["b","Der Uhrmacher (Zeigerkammer): Lupe vorm Auge, Haarkranz, Schnurrbart, lila Weste, Lederschürze, Taschenuhr an der Kette und Schraubenzieher."],["b","Alle drei atmen sichtbar (zwei Bilder) und drehen sich zum Helden; das Porträt im Gespräch zeigt dieselbe Figur."],["b","Ihr Licht ist schwächer und wärmer als bei den gezeichneten Figuren, damit Glatzen und Schädel nicht überstrahlen."],["h","Beim Testen ansehen"],["b","Sind die drei im Raum und im Gesprächsfenster gut zu erkennen? Passt die Größe zum Helden?"]]},{"build": "20261115-0122","title": "Seil-Räume in HD und eine Seillängen-Anzeige","rows": [["h","Neu – Grafik aus Blender"],["b","Glockenstuhl: die große Glocke ist jetzt gegossene Bronze – Krone mit drei Henkeln, Zierbänder, eine Punkt-Inschrift und ein Medaillon; sie schwingt wie bisher nach, wenn man dagegen prallt (BONG). Die Feuerdüsen sind eiserne Löwenköpfe mit glühenden Augen."],["b","Tropfsteinklamm: die Laufkatzen sind Messinggehäuse mit Speichenrädern, die sich beim Fahren drehen; die Schiene ist ein gemaserter Eichenbalken mit eiserner Laufschiene."],["h","Neu – Seillängen-Anzeige"],["b","Solange du am Ring mit ↑ oder ↓ die Länge verstellst, zeigt eine schmale goldene Leiste neben dem Helden, wie lang das Seil gerade ist (oben ganz kurz, unten ganz lang, Striche bei einem Viertel, der Hälfte und drei Vierteln). Kurz nach dem Loslassen blendet sie aus."],["h","Beim Testen ansehen"],["b","Hilft die Seillängen-Anzeige (z. B. an der Glocke oder bei der Kuckucksuhr), oder stört sie? Zu klein, zu groß?"],["b","Sehen Glocke, Laufkatze und Löwenköpfe im Spiel stimmig aus?"]]},{"build": "20261114-1928","title": "Uhrwerk in HD: Blender-Uhren, Zahnrad-Wand, Uhrwerk-Toccata","rows": [["h","Neu – Grafik aus Blender (Richtung HD-3D)"],["b","Kuckucksuhr: Gehäuse mit Schindel-Giebeldach, geschnitztem Blattwerk, Vögelchen auf dem First, Ecksäulen, Geweih und Zifferblatt neu modelliert und beleuchtet gerendert; dazu der Kuckuck selbst (Schnabel zu/offen, kippt beim Sieg schlaff zur Seite), das Pendelgewicht mit Rosette und die Tannenzapfen-Gewichte. Die Türflügel haben jetzt Kassetten."],["b","Zeigerkammer: die beiden großen Zifferblätter mit Messingrand, Minutenteilung und römischen Ziffern, geschmiedete Zeiger mit Lanzenspitze und Gegengewicht, die Stachelnabe als Eisenzahnrad – alles aus Blender, im Spiel weich gedreht."],["b","Zahnrad-Wand: hinter Glockenstuhl, Zeigerkammer und Kuckucksuhr greift eine Kette großer Messing- und kleiner Eisenräder ineinander und dreht sich langsam (richtig übersetzt, mit Tiefenwirkung beim Laufen)."],["p","Neu – Musik: die Uhrwerk-Toccata (Glockenstuhl, Zeigerkammer, Vorraum der Kuckucksuhr)"],["b","d-Moll, 40 Takte in drei Teilen: Zahnrad-Ostinato in Sechzehnteln unter einer Orgelmelodie, eine leichtere Dur-Episode in F, dann eine Steigerung über g-Moll und Es-Dur zurück zum Anfang. Uhrticken als Schlagwerk, Stundenglocke an den Phrasenenden."],["b","Ein Durchgang dauert 73 Sekunden, mit den vier vom Arrangeur variierten Durchgängen knapp 5 Minuten bis zur Wiederholung."],["b","Der Kuckuckswalzer (Bosskampf) ist etwas lauter gemischt und liegt jetzt gleichauf mit den anderen Bossliedern."],["h","Beim Testen ansehen"],["b","Wie klingt die Uhrwerk-Toccata – passt sie zu den Seilräumen, wird sie nicht zu schnell eintönig?"],["b","Lenkt die Zahnrad-Wand ab, oder gibt sie den Räumen Tiefe? (Zu hell / zu unruhig?)"],["b","Läuft es auf der Xbox in Zeigerkammer und Kuckucksuhr weiter flüssig?"]]},{"build": "20261114-1148","title": "Nebenboss: die Kuckucksuhr (Rammstoß am Seil)","rows": [["p","Neu – Nebenboss: die Kuckucksuhr (links hinter der Werkstatt in der Zeigerkammer, Gefahr )"],["b","Unten ein Stachelboden, links und rechts ein Sims, dazwischen zwei Ankerringe. Oben in der Mitte hängt eine riesige Kuckucksuhr, ihr Pendel fegt durch die Mitte des Raums."],["b","Zur vollen Stunde schlägt die Uhr, das Türchen springt auf und der Kuckuck fährt auf einem Scherengitter heraus – bis neben den Ring, an dem du hängst. Nur dann ist er verwundbar (sein Rahmen blinkt)."],["b","Rammstoß: schwing am Seil in ihn hinein. Er kommt entweder ganz nah am Ring heraus (Seil mit ↑ ganz kurz) oder weit unten (Seil mit ↓ ganz lang) – mit mittlerer Länge triffst du nie. Peitschenhiebe zählen auch."],["b","\"KUCKUCK!\" – Noten fliegen auf dich zu (ausweichen mit ↑↓, mit der Peitsche zurückschlagen). Mit langem Seil kommst du dem Pendel gefährlich nah."],["b","Ab halber Kraft: viertelstündlich – er kommt öfter, ruft Noten-Fächer, das Pendel schwingt weiter."],["b","Eigenes Lied: der Kuckuckswalzer (3/4, Uhrticken statt Becken, alle acht Takte die Stundenglocke)."],["b","Lohn: die Kuckucksfeder (Glück +3, MP +6), Bestiarium-Eintrag, Urkunde \"ES HAT DREIZEHN GESCHLAGEN\"."],["b","Vor dem Kampf steht die Uhr still im Raum, nach dem Sieg bleibt sie als Wrack: Türchen offen, Kuckuck schlaff."],["h","Behoben"],["b","Der Glöckner (Glockenstuhl) sprach nur mit Kaspar – mit allen anderen Helden fehlten seine Zeilen (sein Sprecherbuchstabe war für Kaspar reserviert). Jetzt redet er mit allen."],["b","NEU-Markierung: Rahmen, Schilder und Pfeile richten sich jetzt nach dem Weltbild unter dem HUD (Pfeile am unteren Rand konnten abgeschnitten werden)."],["h","Beim Testen ansehen"],["b","Kuckucksuhr: erkennt man früh genug, ob der Kuckuck nah oder weit unten herauskommt? Ist der Kampf zu lang? (Testbot: 8 Rammstöße, gut 45 Sekunden – mit menschlichen Fehlschlägen eher 2 Minuten.)"],["b","Glockenstuhl: spricht der Glöckner jetzt mit jedem Helden?"]]},{"build": "20261114-1036","title": "Zeigerkammer: am Uhrzeiger im Kreis, und \"NEU\" zeigt, was neu ist","rows": [["p","Neu – Raum: die Zeigerkammer (Bergfried, unten links an der Pendelhalle, Gefahr )"],["b","Zwei riesige Zifferblätter, an der Spitze jedes Zeigers ein Ankerring. Der Zeiger dreht sich weiter, während du hängst – du wirst im Kreis getragen (eine Umdrehung: 9 Sekunden). Zeiger A läuft im, Zeiger B gegen den Uhrzeigersinn."],["b","Unten warten Zahnräder mit Stacheln: dort mit ↑ ganz kurz hängen. Mit langem Seil schleift man über die Spitzen."],["b","In der Mitte jedes Zifferblatts eine Stachelnabe: wer oben über die Achse fährt, hält das Seil ganz kurz oder lässt es mit ↓ ganz lang und schwingt darunter durch – mittellang trifft es."],["b","Bei neun Uhr stehen beide Zeiger nah beieinander: loslassen, nach links, B greifen. B trägt dich über seine Nabe hinweg zur Werkstatt."],["b","Die Werkstatt des Uhrmachers: Truhe, Lebensgefäß, Rückweg-Portal und der Uhrmacher, der die Zeit angehalten hat – leider an der falschen Uhr (Gespräch in 8 Sprachen, 1500 G)."],["h","Neu – \"NEU\"-Markierung beim Abschnittswechsel"],["b","Kommst du in einen Raum, in dem sich etwas geändert hat, nennt ein grünes Band die Neuerung, und ein pulsierender Rahmen mit NEU-Schild zeigt die Stelle (liegt sie außerhalb des Bilds: grüner Pfeil am Rand)."],["b","Nur wenn dort wirklich etwas neu ist. Über die Abschnittswahl jedes Mal, beim normalen Spielen einmal je Version."],["b","Die Abschnittswahl markiert jetzt die aktuellen Neuerungen: Zeigerkammer, Pendelhalle (neue Tür), Tropfsteinklamm, Kanal (neuer Ausgang), Glockenstuhl, Bibliothek (neue Tür). Alte Einträge (Bosse u. a.) sind raus."],["h","Behoben"],["b","Im Gespräch stand bei Glöckner und Bergführer der Name des Helden. Jetzt: DER GLÖCKNER, DER BERGFÜHRER, DER UHRMACHER (8 Sprachen)."],["h","Beim Testen ansehen"],["b","Zeigerkammer: ist der Moment bei neun Uhr gut zu erkennen? Ist das Kürzen am Zahnrad zu knapp oder zu leicht?"],["b","Abschnittswahl → ein grün markierter Raum: erscheinen Band und Rahmen, und stören sie nicht beim Losspielen?"]]},{"build": "20261114-0711","title": "Tropfsteinklamm: Seilbahn mit Laufkatzen","rows": [["h","Neu – Laufkatze am Ring"],["b","Ein Ankerring an einer Laufkatze: hakst du ein, rollt sie an der Schiene los und trägt dich mit. Die Seillänge bleibst du selbst (↑ kürzer, ↓ länger). Ohne Fahrgast rollt sie nach kurzer Pause leer zurück."],["b","Fledermausschwärme fliegen in festen Höhen quer durch die Klamm – am Seil weichst du mit der Länge aus."],["p","Neu – Raum: die Tropfsteinklamm (Katakomben, am rechten Ende des unterirdischen Kanals, Gefahr )"],["b","1. Bahn: Stalagmiten von unten, ein Schwarm in mittlerer Höhe (kurz hängen – oder ganz lang), ein hoher Stalagmit (kurz!) und ein tiefer Schwarm. Am Ende auf den Sims fallen lassen (Engel, Kontrollpunkt)."],["b","2. Bahn (tiefer): ein Schwarm knapp unter der Schiene – Seil lang lassen –, dann ein Stalagmit, über den nur mittellang passt. Am Ende mit langem Seil unter den Felsüberhang in den Stollen pendeln."],["b","Im Stollen: Truhe, Lebensgefäß, Rückweg-Portal und der Bergführer, der seit 1840 auf die Talfahrt wartet (Gespräch in 8 Sprachen, Trostprämie 1500 G)."],["b","Ein Sturz in die Spitzen setzt an den Anfang der laufenden Bahn zurück, nicht an den Raumanfang."],["h","Beim Testen ansehen"],["b","Tropfsteinklamm (Kanal bis ganz nach rechts): fühlt sich die Fahrt gut an, sieht man die Schwärme früh genug kommen? Zu schnell, zu langsam, zu knapp?"],["b","Bleibt man nach dem Absturz in der 2. Bahn wirklich auf dem Mittelsims?"]]},{"build": "20261114-0519","title": "Glockenstuhl: Hängeprüfungen am Ring, Seil länger und kürzer","rows": [["h","Neu – Peitsche am Ring"],["b","Seillänge am Ankerring: ↑ holt das Seil ein, ↓ lässt es nach – jetzt bis 120 px (vorher 80), Einholen geht oben flotter. Das Seil knarzt dabei."],["b","Ruhig hängen: solange du das Seil ein- oder ausfährst (ohne ←/→), kommt der Schwung rasch zur Ruhe – so kannst du still hängen und dich nur in der Höhe bewegen. Kleine Restschwünge laufen von selbst aus."],["b","Stacheln am Seil verletzen jetzt (vorher prallte man nur ab) – wer zu lang hängt, fällt."],["p","Neu – Raum: der Glockenstuhl (Bergfried, Bibliothek ganz oben links durch die neue Tür, Gefahr )"],["b","1) Seil kürzen: unter dem ersten Ring eine Stachelsäule. Mit dem normal eingeholten Seil streift man die Spitzen – also ↑ halten, dann hinüberschwingen auf den Sims."],["b","2) Ruhig hängen und ausweichen: Feuerdüsen im Pfeiler schießen im Takt auf vier Höhen. Phase A (oben + Mitte-unten): mittellang hängen; Phase B (Mitte + ganz unten): etwas länger hängen. Dazwischen Zeit zum Umgreifen, danach drei Sekunden Ruhe zum Hinüberschwingen. Unter dem Ring Stacheln: \"einfach ganz lang hängen\" gilt nicht."],["b","3) Seil lang lassen: vor dem Stollen hängt die große Glocke. Mit kurzem Seil prallst du dagegen – BONG – und fällst. Erst mit langem Seil (über ~86 px) schwingst du unter ihrem Rand hindurch in den Stollen."],["b","Im Stollen: Truhe, Lebensgefäß, ein Rückweg-Portal und der Glöckner, der seit 1702 Ohrstöpsel trägt (Gespräch in 8 Sprachen, Schweigegeld 1500 G)."],["b","Die ganze Grube ist mit Stacheln ausgelegt: ein Sturz kostet etwas Leben und setzt an den Anfang des Abschnitts zurück – kein Weg zurück durch den ganzen Raum. Engel auf jedem Sims."],["h","Neu – Feinschliff"],["b","Hinweise eines Raums (\"Spring von Lüster zu Lüster!\") blenden beim Verlassen aus, statt im nächsten Raum zu stehen."],["b","COMBO-Zähler aus, solange das Namensband eines Bosses oder ein Wortgeplänkel steht."],["b","Ballsaal: etwas weniger Glühen, die Lüster (Sprungziele) bleiben als Form erkennbar."],["h","Beim Testen ansehen"],["b","Glockenstuhl: Tür in der Bibliothek ganz oben links (Steg an der Wand). Gelingen die drei Prüfungen? Ist eine zu schwer oder zu knapp getaktet (vor allem das Feuer)? Kommt man nach einem Sturz an der richtigen Stelle wieder heraus?"],["b","Andere Ringe (Kathedrale, Sonnenturm, Kaleidoskop, Seelenstrudel, Eisrutsche): fühlt sich das Schwingen noch richtig an?"],["b","Ballsaal: angenehmer hell oder jetzt zu dunkel?"]]},{"build": "20261114-0138","title": "Feinschliff: Texte passen in allen Sprachen, keine Überlappungen mehr","rows": [["h","Behoben"],["b","Heldenauswahl: lange Titel und Waffen liefen über den Kartenrand (z. B. \"BARBARIAN OF THE NORTH\", \"PUPPET WITHOUT STRINGS\", \"CACCIATORE DI VAMPIRI\", \"FOUET ÉTOILE DU MATIN\"). Die Karten sind etwas breiter; was dann noch zu lang wäre, wird sanft schmaler gesetzt."],["b","Kopfgeld-Seite (Pause → STATUS, ganz nach rechts): die Namensspalte ist nur so breit wie nötig, der Ort bekommt den Rest – \"GALVANI-LABORATORIUM\" steht jetzt ungestaucht da. Auf schmalen Handy-Schirmen werden lange Orte ohne Artikel und an Wortgrenzen gekürzt (\"THRON DER NACHT\") statt auf die Hälfte zusammengequetscht."],["b","Einblendungen am Bildrand (\"KOPFGELD +4000 G\", \"NEU IM BESTIARIUM\"): nach einem Bosssieg schwankt die Kamera – dabei wurden sie am rechten Rand abgeschnitten. Sie bleiben jetzt ganz im Bild."],["b","\"LEVEL UP!\" lag nach dem Bosssieg halb hinter dem Hinweisband (\"SIEGEL 1/5 – EIN NEUER WEG IST OFFEN\") und steht jetzt darunter."],["b","COMBO-Zähler lugte oben links unter dem Gesprächskasten hervor; solange jemand redet, ist er ausgeblendet."],["b","Urkunden- und Hinweis-Einblendungen brechen auf schmalen Schirmen in zwei Zeilen um, statt gestaucht zu werden."],["h","Beim Testen ansehen"],["b","Heldenauswahl in Englisch, Französisch und Italienisch: steht jeder Titel sauber innerhalb seiner Karte?"],["b","Einen Boss besiegen (z. B. Knochenriese in der Gruft) und am rechten Rand stehen bleiben: Kopfgeld-Zahl ganz zu sehen, \"LEVEL UP!\" unter dem Siegel-Band?"],["b","Auf dem Handy hochkant: Kopfgeld-Seite und Urkunden-Einblendung lesbar?"]]},{"build": "20261113-1822","title": "Hintergründe: Uhrturm und Grotte aus Blender","rows": [["h","Neu – Grafik"],["b","Uhrturm (Bergfried: Uhrwerk-Räume, Pendelhalle): statt der glatten Ziegelwand eine Quaderwand mit Pilastern, Eichenbalken mit Eisenbändern und Nieten, Kopfbändern, hängenden Ketten und drei Spitzbogenfenstern mit rotem Glas. Die große Uhr sitzt jetzt in einem Ring aus Bogensteinen. Zifferblatt, Zeiger, Pendel und Zahnräder sind unverändert."],["b","Grotte (Katakomben-Eingang, unterirdischer Kanal, Golemstollen): die Felswand hat echtes Relief mit Graten und Spalten, von links warm und von rechts kühl beleuchtet, dazu ferner Kristallschein; die Tropfsteinsäulen sind neu. Kristalle, Pilze, Wurzeln und Tropfsteine im Vordergrund bleiben."],["h","Beim Testen ansehen"],["b","Bergfried: erster Raum, Uhrwerk mit den großen Zahnrädern, Pendelhalle (hoher Raum – die Wand stapelt sich nach oben). Sitzen Uhr und Pendel sauber im Steinring, fallen die roten Lichtbahnen aus den Fenstern?"],["b","Katakomben-Eingang und Golemstollen: ist die Felswand zu unruhig oder zu hell hinter Held und Gegnern?"]]},{"build": "20261113-1353","title": "Hintergrund: die Gruft als Steinarkade aus Blender","rows": [["h","Neu – Grafik"],["b","Gruft-Räume (Kerker, Gruft, Gruftgang, versunkene Kapelle, Verlies) haben einen neuen Hintergrund aus Blender: eine Arkadenwand aus Quadern mit Bogensteinen, Pfeilern und Gesims statt der glatten blauen Ziegelwand. In den Bögen wechseln sich ab: ein Beinhaus mit Schädelregalen im Kerzenschein, ein offener Bogen, ein Sarkophag mit Goldkreuz und zwei Kerzen, ein Eisengitter vor bläulichem Schimmer."],["b","Zweite Ebene in der Tiefe: durch den offenen Bogen sieht man ferne Arkaden in zwei Geschossen, die sich beim Laufen langsamer verschieben als die Wand. Die Säulen im Vordergrund bleiben."],["b","Bis die Bilder geladen sind, steht kurz der alte Hintergrund da; Spielfläche und Kacheln sind unverändert."],["h","Beim Testen ansehen"],["b","Katakomben: Kerker, Gruft (Bossraum des Knochenriesen), Gruftgang; dazu die versunkene Kapelle (hoher Raum – dort stapelt sich die Arkade nach oben) und das Verlies. Sind Held, Gegner und Kerzen vor der neuen Wand gut zu erkennen?"],["b","Ist die Wand zu hell, zu dunkel oder zu unruhig? Stört irgendwo eine Naht, wenn die Kamera läuft?"]]},{"build": "20261113-1334","title": "Eigene Mittelteile für die Hauptthemen, flottere Aufzüge, Sammelgegenstände neu","rows": [["h","Neu – Musik"],["b","Burghof, Katakomben, Bergfried und das Bosslied haben für ihre Brücke jetzt eine eigens geschriebene Melodie (getragene Blechlinie über den Akkorden des Stücks, eine Quarte höher); beim zweiten Durchlauf der Melodie spielt die Flöte eine Oktave höher mit. Die übrigen Stücke behalten das Thema, das der Arrangeur aus den Akkorden bildet."],["h","Neu – weniger Warten"],["b","Plattform-Aufzüge (die pendelnden Plattformen an Seilen) fahren deutlich schneller. Stehst du drauf, fahren sie nach einem Augenblick los; wartest du am anderen Ende, kommen sie sofort, statt ihre Pause abzusitzen."],["b","Kabinenaufzüge ohne eigenes Tempo (z. B. im Hotel Krat) fahren fast doppelt so schnell."],["h","Neu – Grafik"],["b","Sammelgegenstände neu aus Blender: kleines und großes Herz, roter und violetter Geldsack, Braten, Kristallkugel. Das kleine Herz ist auch der Zeiger in den Menüs."],["h","Beim Testen ansehen"],["b","Musik: in Burghof, Katakomben oder Bergfried etwa eine Minute bleiben – nach dem ruhigen Flötenteil kommt die neue Blechmelodie. Klingt sie stimmig zum Stück? (Ich konnte nur Pegel messen, nicht hören.)"],["b","Plattform-Aufzüge (Katakomben-Schacht, Uhrturm): fährt die Plattform los, sobald du draufstehst, und kommt sie, wenn du unten oder oben wartest? Ist ein Sprung dadurch schwerer geworden?"],["b","Herzen, Geldsäcke, Braten: gut zu erkennen, auch im Flug und vor hellem Hintergrund?"]]},{"build": "20261113-1319","title": "Musik in langer Form mit Orchester, Schnellreise zu jedem Raum, Paternoster im Eilgang, Requisiten neu","rows": [["h","Neu – Musik (alle Stücke)"],["b","Längere Schleifen: jedes Stück läuft jetzt 2 bis 4 Minuten, bevor es sich wiederholt (vorher 9 bis 63 Sekunden; das Bosslied z. B. 80 statt 10 Sekunden, der Burghof 175 statt 44)."],["b","Mehrere Durchgänge, jeder anders besetzt: Original → Kammerbesetzung (Flöte führt, Harfe begleitet, kaum Schlagzeug; bei Bossliedern stattdessen Streicher mit vollem Schlagzeug) → Brücke in einer anderen Tonart mit einem neuen Blechthema über liegenden Streichern → Tutti mit Streichern, Glockenspiel und Pauken. Kurze Stücke bekommen dazu ein Zwischenspiel ohne Melodie und einen Durchgang eine Mollterz höher."],["b","Neue Instrumente: Streicher, Blech, Flöte, Harfe, Glockenspiel und Pauken (auf den Bass gestimmt)."],["b","Der erste Durchgang ist jeweils das bisherige Stück; das Taktduell am Grammophon ist unverändert."],["h","Neu – weniger Lauferei"],["b","Schnellreise zu jedem schon betretenen Raum (Pause → SCHNELLREISE oder ↓ + Karte): Ziel ist der Raumeingang. Warpkammern und Bossräume bleiben wie bisher. Vorgewählt ist das Ziel, das dem Wegweiser am nächsten liegt. Die Pfeiltasten springen auf der Karte zum nächsten Ziel in dieser Richtung."],["b","Paternoster im Eilgang: sobald du in einer Kabine stehst, läuft der Umlauf gut dreimal so schnell (vier Stockwerke in 3 statt knapp 10 Sekunden). Hältst du ← oder →, bremst er, und du steigst am nächsten Stockwerk aus."],["h","Neu – Grafik"],["b","Paternoster-Kabine neu aus Blender: Mahagoni-Kassetten, Messingpfosten mit Konsolen, Handlauf, Deckenlampe."],["b","Kerzen, Fackeln, Standleuchter und Feuerschalen neu aus Blender (gedrechseltes Messing, Dreifuß, Flammenbilder)."],["h","Beim Testen ansehen"],["b","Musik: ein Stück zwei, drei Minuten laufen lassen (Burghof, Katakomben, ein Bosskampf). Passen die Übergänge zwischen den Durchgängen, ist ein Teil zu laut, zu leise oder schräg? Ich konnte nur Pegel messen, nicht hören."],["b","Schnellreise: Karte öffnen, mit den Pfeilen ein paar Räume ansteuern, reisen. Kommst du an einer sinnvollen Stelle an?"],["b","Paternoster (Behördentrakt): Fahrt im Eilgang, Aussteigen mit gehaltener Richtung auf jedem Stockwerk, oben durchfahren."],["b","Kerzen und Fackeln in jedem Raum, Standleuchter und Feuerschalen im Bergfried und im Thronbereich: gut erkennbar?"]]},{"build": "20261113-0717","title": "Hotfix: Wegweiser im Eiskeller zeigte in eine Sackgasse","rows": [["h","Behoben"],["b","Eiskeller (Katakomben, unter der Eisrutsche): Der Wegweiser zeigte auf den Schacht in der Decke. Das ist nur der Fallschacht der Eisrutsche – von unten kommt man dort nicht hinauf. Der Schacht zählt jetzt als Einbahn: der Wegweiser führt nach rechts zum Eisaufzug (↑ ruft die Kabine, ↑ auf der Kabine fährt hinauf zur Eishöhle) oder nach links zum Golemstollen. Dasselbe gilt für das obere Ende der Eisrutsche."],["b","Der Selbsttest prüft jetzt jeden Schacht nach oben: ohne Aufzug, Treppe oder Boden in Sprunghöhe wird er gemeldet."],["h","Beim Testen ansehen"],["b","Im Eiskeller: zeigt der Pfeil nach rechts (bzw. links zum Golem), und kommst du über den Eisaufzug wieder hinauf?"]]},{"build": "20261113-0229","title": "Grafik: Medusa und die kleinen Kreaturen neu aus Blender","rows": [["h","Neu – Grafik"],["b","Medusa neu modelliert: Gesicht mit leuchtenden Schlitzaugen, Diadem mit Rubin, Goldkragen, Schuppenmieder, Gürtel, Armreife und Krallenhände; beim Fauchen reißt sie beide Arme hoch und zeigt die Giftzähne. Der Schlangenleib beginnt als zwei Windungen mit hellen Bauchschilden und geht in den gezeichneten Schwanz über. Das bewegte Schlangenhaar bleibt."],["b","Medusenhäupter (fliegende Köpfe): größeres Gesicht mit Augen, Diadem und kurzem Schlangenhaar."],["b","Gespenst: Laken mit Zipfel, welligem Saum und kleinen Ärmchen."],["b","Flammenschädel: runder Schädel mit glühender Augenhöhle und Kiefer, dahinter ein dreifarbiger Flammenschweif."],["b","Seeadler: weißer Kopf und Schwanz, gelber Schnabel, breitere Schwingen mit dunklen Schwungfedern."],["b","Rabe: etwas kräftiger, blauschwarzes Gefieder, rotes Auge."],["b","Knochensäule: zwei gehörnte Drachenschädel mit Zahnreihe auf einer Wirbelsäule; beim Feuern klappt der obere Rachen auf und zeigt die Glut."],["b","Bildgrößen, Trefferflächen und Verhalten sind unverändert – nur die Bilder sind neu."],["h","Beim Testen ansehen"],["b","Bergfried, Boss Medusa: passt der Übergang vom Leib zum Schwanz am Boden, liegen die glühenden Augen beim Versteinerungsblick auf dem Gesicht, verdeckt das Schlangenhaar das Gesicht nicht zu sehr?"],["b","Medusenhäupter (Medusas Angriff) und Flammenschädel: gut zu erkennen, auch wenn sie leuchten?"],["b","Bergfried, erster Raum: Knochensäule – sieht das aufklappende Maul beim Feuern richtig aus, in beide Blickrichtungen?"],["b","Ankunft (Schiff): Seeadler und Raben; Burghof und Katakomben: Gespenster. Sind die kleinen Vögel vor dunklem Hintergrund noch gut zu sehen?"]]},{"build": "20261113-0153","title": "Grafik, Gameplay, Musik: Skelette und Sonnenwächter neu, Kopfgeld-Seite, Portal, zweite Stimme","rows": [["h","Neu – Grafik"],["b","Skelett, Knochenriese und Sonnenwächter neu aus Blender: Schädel mit Augenhöhlen, Rippenbögen, dünne Knochen; der Sonnenwächter in glänzender Goldrüstung mit Stahl-Kniebuckeln, weißem Federbusch und Schild. Auch der Ritter glänzt jetzt. Damit kommen alle Figuren, die aus dem Gelenk-Rig entstehen, aus derselben Render-Strecke wie die Helden."],["h","Neu – Gameplay"],["b","Statusseite KOPFGELD (Pause → STATUS, ganz nach rechts blättern): alle 16 Bosse als Steckbriefliste mit Ort und Lohn; erledigte haben einen Haken, das aktuelle Ziel des Wegweisers blinkt."],["b","Rückweg-Portal: nach jedem Bosssieg erscheint neben dem Helden ein blaues Portal. ↑ davor öffnet die Schnellreise. Es bleibt, bis man den Raum verlässt."],["h","Neu – Musik"],["b","Die drei Hauptthemen (Burghof, Katakomben, Bergfried) haben eine neue Begleitstimme: im ersten Durchgang ruhige gebrochene Akkorde in Achteln statt der schnellen 16tel-/32tel-Arpeggien, in der Wiederholung singt die zweite Stimme die Melodie eine Terz tiefer mit."],["h","Beim Testen ansehen"],["b","Katakomben (Skelette, Knochenriese), Sonnenkathedrale (Sonnenwächter): passen Größe und Trefferfläche, sieht der Lanzenstoß des Sonnenwächters noch richtig aus?"],["b","KOPFGELD-Seite auf deinem Bildschirm: ist alles lesbar, stimmen die Haken mit deinem Spielstand?"],["b","Portal nach einem Bosssieg: steht es frei (nicht in einer Wand oder auf einer Tür), reagiert ↑ zuverlässig?"],["b","Musik: klingt die Terzstimme in allen drei Stücken sauber, oder reibt sie sich irgendwo mit Bass und Fläche?"]]},{"build": "20261113-0134","title": "Changelog im Spiel","rows": [["h","Neu"],["b","Optionen → CHANGELOG zeigt dieses Changelog im Spiel: ↑↓ rollt (gehalten läuft es weiter), ←→ springt zur vorigen oder nächsten Version, Start, Sprung oder Angriff führt zurück. In der Optionszeile steht die neueste Build-Nummer."],["b","Der Text kommt aus CHANGELOG.md (python tools/make_changelog.py erzeugt daraus js/changelog.js) und ist auf Deutsch, auch wenn das Spiel auf eine andere Sprache gestellt ist."],["h","Beim Testen ansehen"],["b","Titel → OPTIONEN → ganz nach unten: steht CHANGELOG vor ZURÜCK, stimmt die Build-Nummer mit dem Titelbild überein?"],["b","Ist die Seite auf deinem Bildschirm gut lesbar, rollt sie flüssig, sind lange Zeilen sauber umbrochen?"]]},{"build": "20261113-0128","title": "Grafik: Riesenfledermaus und Gegner neu aus Blender","rows": [["h","Neu"],["b","Riesenfledermaus (erster Hauptboss) ist in Blender neu modelliert: pelziger Leib mit hellem Bauch, Kopf mit Ohren und glühenden Augen, Flügel mit Arm, vier Fingerknochen und gewölbten Hautfeldern, aufgerissenes Maul mit Fängen beim Sturzflug und beim Schießen, ruhend mit angelegten Flügeln. 17 Bilder, gleiche Größe und Lage wie vorher."],["b","Ghul, Fischmensch und Ritter neu aus derselben Render-Strecke wie die Helden: runder, mit Licht von oben links, der Ritter mit Helm, Federbusch und blauem Schild, der Fischmensch mit Flossenkamm und hellem Kehlsack."],["b","Diese Version liegt nur auf GitHub Pages (itch.io und Game Jolt stehen noch auf 20261112-0614)."],["h","Beim Testen ansehen"],["b","Große Halle: Riesenfledermaus in allen Phasen – schlafend an der Decke, Flügelschlag, Sturzflug mit offenem Maul. Passt die Trefferfläche noch zum Bild?"],["b","Ghule (Katakomben), Fischmenschen (am Wasser), Ritter (Burghof/Bergfried): passen sie neben den neuen Helden ins Bild?"],["b","Noch im alten Stil: Skelette, Knochenriese, Sonnenwächter, Medusa, Raben, Geister."]]},{"build": "20261112-1414","title": "Fluss: schneller zurück zum Boss, Lohn nach jedem Sieg","rows": [["h","Neu"],["b","Bossräume als Reiseziele: Hast du den Raum eines noch unbesiegten Bosses einmal betreten, steht er in der Schnellreise (orange beschriftet, z. B. \"NEBENBOSS: DER ZUGFÜHRER\"). Die Reise setzt dich am Eingang dieses Raums ab – nach einer Niederlage entfällt der lange Anmarsch. Vorgewählt ist der Raum des aktuellen Ziels, wenn er schon bekannt ist."],["b","↓ + Karte (Tab/Q bzw. Select) öffnet die Schnellreise direkt aus dem Spiel, ohne Pausenmenü."],["b","Lohn nach jedem Bosssieg: Kopfgeld (Nebenboss 1000 G je Gefahrenstufe, Hauptboss 2000 G je Stufe), HP und MP sind danach voll. Beim ersten Sieg erscheint einmal der Hinweis auf die Schnellreise."],["b","Nach der Schnellreise aus dem Pausenmenü ist die Musik wieder normal laut (die Pause-Dämpfung wird gelöst)."],["h","Beim Testen ansehen"],["b","Einen Bossraum betreten, wieder hinausgehen, dann Pause → SCHNELLREISE: steht der Raum in der Liste, kommt man am Eingang an und beginnt der Kampf normal?"],["b","↓ + Karte im Laufen, im Sprung, auf Treppen: öffnet sich die Reise nur, wenn man es will (↓ wird auch zum Ducken benutzt)?"],["b","Ist das Kopfgeld zu großzügig oder zu knapp? Fühlt sich das volle Auffüllen nach Bossen richtig an?"],["b","Bekannt offen: Abkürzungen als echte Türen zwischen Regionen und ein sichtbares Portal in der Arena gibt es noch nicht."]]},{"build": "20261112-0614","title": "Alle Bosse im Schloss, weniger Lauferei","rows": [["h","Neu"],["b","Nebenbosse sind Ziele des Wegweisers. Bisher führte der goldene Pfeil nur über den Hauptweg; Zugführer, Amtsschimmel, Frankiermaschine, Schreibtischtäter, Sternbild, Mann im Mond, Reißwolf, Golem, Doppelgänger und der Erwachte (Frankensteins Geschöpf) musste man selbst finden. Jetzt schickt der Wegweiser zu ihnen, sobald der Hauptweg eine höhere Gefahrenstufe erreicht hat und das Tor zu ihrem Bereich offen ist – leichtere zuerst, dann der nähere. Anzeige: \"NEBENBOSS: …\" mit dem Raum."],["b","Bosszähler auf der Statusseite: BOSSE x/16 (sechs Hauptbosse, zehn Nebenbosse)."],["b","Schnellreise von überall: Pause → SCHNELLREISE öffnet die Karte der schon betretenen Warpkammern. Vorgewählt ist die Kammer in der Region des aktuellen Ziels. Nicht im Bosskampf und nicht im Vorspiel."],["b","Zum Mond führt das Ziel über die Sternkuppel (Mondkanone), sobald das Sternbild besiegt ist."],["h","Beim Testen ansehen"],["b","Zeigt der Pfeil nach einem Hauptboss sinnvoll auf einen Nebenboss? Ist der Weg dorthin ohne fehlendes Relikt gehbar? (Der Wegweiser prüft nur Tore, nicht Sprunghöhen – falls er zu einem Boss schickt, den man noch nicht erreichen kann, bitte melden.)"],["b","Schnellreise: kommt man in der gewählten Warpkammer an, stimmt danach die Musik der Region?"],["b","Fühlt sich die Reihenfolge der Nebenbosse richtig an (acht davon haben Gefahrenstufe 3)?"]]},{"build": "20261112-0201","title": "Helden und Graf neu aus Blender, ruhigere Musik","rows": [["h","Neu"],["b","Henrik, Ragnor, Kaspar und Henrik im Abenteurer-Look sind in Blender neu modelliert und gerendert (47 Posen je Figur)."],["b","Der Graf (Dracula) ist neu: gefalteter Umhang mit gebogtem Saum, spitzer Kragen, Frack mit Weste und Orden."],["b","Musik: Rock-Takt statt Vier-auf-den-Boden, keine zufällig betonten Hi-Hats mehr, das Pumpen bei jeder Kick ist fast weg, zweite Stimme und Streicher stehen weiter vorn."],["h","Beim Testen ansehen"],["b","Heldenwahl im Titel: sehen alle drei Helden (und Henriks zweiter Look mit ▲▼) in allen Bewegungen sauber aus – Laufen, Springen, Ducken, Treppen, Angriff, Treffer?"],["b","Thronsaal: der Graf in allen drei Haltungen (Umhang zu, offen, Arme erhoben), sitzt das Augenglühen auf den Augen?"],["b","Musik in Burghof, Katakomben, Bergfried: stolpert das Schlagzeug noch? Ist es zu leise geworden?"]]},{"build": "20261112-0056","title": "Lesbare Schrift, neue Fledermaus","rows": [["h","Neu"],["b","Gold steht mit Münze unter den Leisten (stieß vorher an das Waffenfach)."],["b","Status, Karte und alle Menüseiten sind deckend – das HUD scheint nicht mehr als blasse Schrift durch."],["b","Zu breite Zeilen werden lesbar schmaler (erst schmalere Leerzeichen, dann geglättet) statt zu Pixelbrei gestaucht."],["b","Fledermäuse neu als Pixelgrafik: Flughäute, Ohren, glühende Augen, 16 Flügelschlag-Phasen, ruhend kopfüber."],["h","Beim Testen ansehen"],["b","HUD und alle Menüseiten auf dem eigenen Bildschirm: ist noch irgendwo Schrift verdeckt oder abgeschnitten?"],["b","Auf dem Handy (hoch und quer): Zauber-, Urkunden-, Mahre- und Ausrüstungsseite."]]},{"build": "20261111-2152","title": "Bodenschatten, Beute-Magnet, Ruf-Schnellwechsel","rows": [["h","Neu"],["b","Bodenschatten unter Held, Gegnern und Beute (im Sprung kleiner und blasser)."],["b","Herzen und Gold kommen dem Helden die letzten Schritte entgegen."],["b","Kritische Treffer schieben laufende Gegner ein Stück zurück; der Stufenaufstieg füllt die MP."],["b","↑ + Karte wechselt im Spiel zum nächsten gefangenen Ruf-Mahr (ab zwei Ruf-Mahren)."],["b","Der Zweig mit den Verbesserungen für schmale Schirme, Bosskammern und Ladehänger ist eingemischt."],["h","Beim Testen ansehen"],["b","Schatten auf Treppen, Plattformen und Aufzügen; stört der Magnet beim gezielten Liegenlassen von Beute?"]]},{"build": "20261111-1713","title": "Feinschliff an Ton, Grafik und Gefühl","rows": [["h","Neu"],["b","Acht neue Geräusche (Mahr steigt auf, Fang, Ruf, leere MP, Geisterhaut, Versteinerung, kritischer Treffer, Herzschlag); oft gehörte Geräusche klingen jedes Mal leicht anders."],["b","Bei wenig HP: Herzschlag, die Musik rückt in den Hintergrund."],["b","Zauberkreis beim Ruf, Stern beim kritischen Treffer, violettes Glimmen an Gegnern, deren Mahr noch fehlt."],["b","Versteinerte Gegner sind spröde (Treffer x1,5). Perfektes Ausweichen gibt 6 MP, und in der Zeitlupe danach ist jeder Hieb kritisch."],["b","HUD: grüner Blitz bei Heilung, Medaillon blitzt beim Stufenaufstieg, MP-Zahl blinkt rot, wenn der Ruf nicht bezahlbar ist."]]},{"build": "20261111-1659","title": "Mahre, kritische Treffer, neues Schloss-HUD","rows": [["h","Neu"],["b","Mahre: besiegte Gegner lassen manchmal ihren Mahr zurück, der im Traumfänger landet. Zehn Ruf-Mahre (↑ + SUB, kosten MP) und acht Bann-Mahre (wirken dauernd), je Platz einer, Rang I–IX. Pause → STATUS → Seite MAHRE."],["b","Kritische Treffer (Glück, Bann-Mahr \"Raubtierblick\"): goldene Zahl mit \"!\", Schaden x1,75."],["b","Schloss-HUD: Medaillon mit Stufe und EXP-Ring, glatte HP-/MP-Leisten mit Zahl, Bossleiste nur im Kampf, Ruf-Mahr im Waffenfach."],["h","Beim Testen ansehen"],["b","Der erste besiegte Gegner mit Mahr (z. B. Skelett) gibt ihn sicher; danach Fangquote und Ränge."],["b","Balance der Ruf-Mahre gegen normale Gegner und Bosse."]]}];
